{
  "name": "EduMind: Pedagogical Decision Support System",
  "description": "A comprehensive student performance analysis tool based on Circular 22 (TT22), providing strategic insights and progress goals for educators."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum SubjectLevel {
  TOT = 'TỐT',
  KHA = 'KHÁ',
  DAT = 'ĐẠT',
  CHUA_DAT = 'CHƯA ĐẠT'
}

export enum StudentClassification {
  TOT = 'Học sinh TỐT',
  TIEM_CAN_TOT = 'Tiệm cận TỐT',
  DAT_CAN_DAU_TU = 'ĐẠT (Cần đầu tư)',
  NGUY_CO = 'Nguy cơ (Tiệm cận Chưa Đạt)',
  CHUA_DAT = 'CHƯA ĐẠT'
}

export interface SubjectScore {
  name: string;
  score: number;
  level: SubjectLevel;
}

export interface Goal {
  subjectName: string;
  currentScore: number;
  targetScore: number;
  increment: number;
  description: string;
}

export interface StudentData {
  id: number;
  name: string;
  className: string;
  scores: SubjectScore[];
  classification: StudentClassification;
  summary: string;
  goals: Goal[];
  prioritySubjects: string[];
}

export interface ClassStats {
  total: number;
  totCount: number;
  tiemCanTotCount: number;
  datCount: number;
  nguyCoCount: number;
  chuaDatCount: number;
}

import { SubjectLevel, StudentClassification, SubjectScore, StudentData, Goal } from './types';

export const getSubjectLevel = (score: number): SubjectLevel => {
  if (score >= 8.0) return SubjectLevel.TOT;
  if (score >= 6.5) return SubjectLevel.KHA;
  if (score >= 5.0) return SubjectLevel.DAT;
  return SubjectLevel.CHUA_DAT;
};

export const processRawStudentData = (
  raw: any, 
  subjectHeaders: string[]
): StudentData | null => {
  try {
    const scores: SubjectScore[] = subjectHeaders.map(header => {
      const score = parseFloat(raw[header]);
      if (isNaN(score) || score < 0 || score > 10) {
        throw new Error(`Dữ liệu không hợp lệ ở môn ${header}`);
      }
      return {
        name: header,
        score,
        level: getSubjectLevel(score)
      };
    });

    const totCount = scores.filter(s => s.level === SubjectLevel.TOT).length;
    const khaCount = scores.filter(s => s.level === SubjectLevel.KHA).length;
    const datCount = scores.filter(s => s.level === SubjectLevel.DAT).length;
    const chuaDatCount = scores.filter(s => s.level === SubjectLevel.CHUA_DAT).length;
    const totalSubjects = scores.length;
    const totPercentage = (totCount / totalSubjects) * 100;

    let classification: StudentClassification = StudentClassification.CHUA_DAT;
    let summary = "";
    let goals: Goal[] = [];
    let prioritySubjects: string[] = [];

    // Decision Logic

    // 1. TOT
    if (totPercentage >= 80 && chuaDatCount === 0 && khaCount <= 1 && datCount === 0) {
      classification = StudentClassification.TOT;
      summary = "Duy trì và mở rộng năng lực vượt trội.";
    } 
    // 2. TIEM CAN TOT
    else if (totPercentage >= 60 && totPercentage < 80 && khaCount <= 2 && datCount === 0 && chuaDatCount === 0) {
      classification = StudentClassification.TIEM_CAN_TOT;
      summary = "Có tiềm năng lớn để đạt mức TỐT toàn diện.";
      const khaSubjects = scores.filter(s => s.level === SubjectLevel.KHA);
      goals = khaSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: Math.min(10, s.score + 0.6),
        increment: 0.6,
        description: "Mục tiêu nâng mức KHÁ lên TỐT."
      }));
      prioritySubjects = khaSubjects.map(s => s.name);
    }
    // 4. NGUY CO (High priority for early intervention)
    else if (scores.some(s => s.score >= 4.5 && s.score < 5.0) || scores.filter(s => s.score < 5.5).length >= 2) {
      classification = StudentClassification.NGUY_CO;
      summary = "Nguy cơ không đạt. Cần can thiệp hỗ trợ sớm.";
      const lowScores = [...scores].sort((a, b) => a.score - b.score).slice(0, 2);
      goals = lowScores.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Mục tiêu ngắn hạn: Vượt ngưỡng 5.0."
      }));
      prioritySubjects = lowScores.map(s => s.name);
    }
    // 5. CHUA DAT
    else if (chuaDatCount > 0) {
      classification = StudentClassification.CHUA_DAT;
      summary = "Chưa hoàn thành mục tiêu học tập tối thiểu.";
      const failedSubjects = scores.filter(s => s.level === SubjectLevel.CHUA_DAT);
      goals = failedSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Khoảng cách cần bù đắp để đạt mức tối thiểu."
      }));
      prioritySubjects = failedSubjects.map(s => s.name);
    }
    // 3. DAT (Needs investment)
    else {
      classification = StudentClassification.DAT_CAN_DAU_TU;
      summary = "Đã đạt yêu cầu nhưng cần đầu tư thêm ở một số môn.";
      const lowDatSubjects = scores.filter(s => s.level === SubjectLevel.DAT).sort((a, b) => a.score - b.score);
      goals = lowDatSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 6.5,
        increment: 6.5 - s.score,
        description: "Mục tiêu nâng mức ĐẠT lên KHÁ."
      }));
      prioritySubjects = lowDatSubjects.map(s => s.name);
    }

    return {
      id: parseInt(raw['STT']) || Math.random(),
      name: raw['Họ tên'] || 'N/A',
      className: raw['Lớp'] || 'N/A',
      scores,
      classification,
      summary,
      goals,
      prioritySubjects
    };
  } catch (err) {
    console.error("Error processing student:", err);
    return null;
  }
};

import { GoogleGenAI } from "@google/genai";
import { StudentData, ClassStats } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getPedagogicalAdvice = async (stats: ClassStats, students: StudentData[]): Promise<string> => {
  try {
    const prompt = `
      Dưới đây là thống kê kết quả học tập của một lớp:
      - Tổng số học sinh: ${stats.total}
      - Tốt: ${stats.totCount}
      - Tiệm cận Tốt: ${stats.tiemCanTotCount}
      - Đạt (Cần đầu tư): ${stats.datCount}
      - Nguy cơ: ${stats.nguyCoCount}
      - Chưa đạt: ${stats.chuaDatCount}

      Hãy đóng vai một chuyên gia tư vấn giáo dục, phân tích tình hình và đưa ra 3 lời khuyên chiến lược cho giáo viên chủ nhiệm để cải thiện chất lượng học tập trong học kỳ tới. Viết ngắn gọn, súc tích bằng tiếng Việt.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Không thể tải lời khuyên từ AI.";
  } catch (error) {
    console.error("Error fetching AI advice:", error);
    return "Hãy tập trung hỗ trợ nhóm học sinh nguy cơ và bồi dưỡng nhóm tiệm cận tốt.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  Upload, 
  FileText, 
  Download, 
  AlertCircle, 
  TrendingUp, 
  Target, 
  Users, 
  ChevronRight,
  Sparkles,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  BarChart3
} from 'lucide-react';
import { StudentData, ClassStats, StudentClassification } from './types';
import { processRawStudentData } from './gradingService';
import { getPedagogicalAdvice } from './geminiService';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie
} from 'recharts';

const App: React.FC = () => {
  const [students, setStudents] = useState<StudentData[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedClassification, setSelectedClassification] = useState<string>("All");

  const stats = useMemo((): ClassStats => {
    return {
      total: students.length,
      totCount: students.filter(s => s.classification === StudentClassification.TOT).length,
      tiemCanTotCount: students.filter(s => s.classification === StudentClassification.TIEM_CAN_TOT).length,
      datCount: students.filter(s => s.classification === StudentClassification.DAT_CAN_DAU_TU).length,
      nguyCoCount: students.filter(s => s.classification === StudentClassification.NGUY_CO).length,
      chuaDatCount: students.filter(s => s.classification === StudentClassification.CHUA_DAT).length,
    };
  }, [students]);

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const matchesSearch = s.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            s.className.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = selectedClassification === "All" || s.classification === selectedClassification;
      return matchesSearch && matchesFilter;
    });
  }, [students, searchTerm, selectedClassification]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json<any>(ws);

        if (data.length === 0) {
          throw new Error("File trống hoặc sai định dạng.");
        }

        const allHeaders = Object.keys(data[0]);
        const subjectHeaders = allHeaders.filter(h => 
          !['STT', 'Họ tên', 'Lớp'].includes(h)
        );

        setHeaders(subjectHeaders);

        const processed = data.map(item => processRawStudentData(item, subjectHeaders))
                             .filter((s): s is StudentData => s !== null);

        setStudents(processed);
      } catch (err: any) {
        setError(err.message || "Lỗi khi xử lý file Excel.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const loadAiAdvice = async () => {
    if (students.length === 0) return;
    setAiAdvice("Đang phân tích dữ liệu...");
    const advice = await getPedagogicalAdvice(stats, students);
    setAiAdvice(advice);
  };

  const exportToExcel = () => {
    const dataToExport = students.map(s => ({
      'STT': s.id,
      'Họ tên': s.name,
      'Lớp': s.className,
      'Phân loại': s.classification,
      'Ghi chú': s.summary,
      'Môn trọng tâm': s.prioritySubjects.join(', '),
      'Mục tiêu tiến bộ': s.goals.map(g => `${g.subjectName} -> ${g.targetScore}`).join('; ')
    }));
    const ws = XLSX.utils.json_to_sheet(dataToExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Báo cáo");
    XLSX.writeFile(wb, "Bao_cao_hoc_sinh.xlsx");
  };

  const getClassificationColor = (cls: StudentClassification) => {
    switch (cls) {
      case StudentClassification.TOT: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case StudentClassification.TIEM_CAN_TOT: return 'bg-blue-100 text-blue-700 border-blue-200';
      case StudentClassification.DAT_CAN_DAU_TU: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
      case StudentClassification.NGUY_CO: return 'bg-orange-100 text-orange-700 border-orange-200';
      case StudentClassification.CHUA_DAT: return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const chartData = [
    { name: 'Tốt', count: stats.totCount, color: '#10b981' },
    { name: 'Tiệm cận Tốt', count: stats.tiemCanTotCount, color: '#3b82f6' },
    { name: 'Đạt', count: stats.datCount, color: '#eab308' },
    { name: 'Nguy cơ', count: stats.nguyCoCount, color: '#f97316' },
    { name: 'Chưa đạt', count: stats.chuaDatCount, color: '#f43f5e' },
  ];

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-600 rounded-lg">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 hidden sm:block">EduMind <span className="text-indigo-600 font-medium">TT22</span></h1>
          </div>
          <div className="flex items-center gap-4">
            {students.length > 0 && (
              <button 
                onClick={exportToExcel}
                className="flex items-center gap-2 px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition text-sm font-medium"
              >
                <Download className="w-4 h-4" /> Xuất Excel
              </button>
            )}
            <label className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm font-medium">
              <Upload className="w-4 h-4" /> {students.length === 0 ? "Tải lên Excel" : "Cập nhật dữ liệu"}
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 w-full">
        {error && (
          <div className="mb-6 p-4 bg-rose-50 border border-rose-200 text-rose-700 rounded-xl flex items-start gap-3">
            <AlertCircle className="w-5 h-5 mt-0.5 shrink-0" />
            <div>
              <p className="font-semibold">Lỗi xử lý dữ liệu</p>
              <p className="text-sm">{error}</p>
            </div>
          </div>
        )}

        {students.length === 0 ? (
          <div className="flex flex-col items-center justify-center min-h-[60vh] text-center">
            <div className="w-20 h-20 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mb-6">
              <FileText className="w-10 h-10" />
            </div>
            <h2 className="text-2xl font-bold text-slate-900 mb-2">Hỗ trợ ra quyết định sư phạm</h2>
            <p className="text-slate-500 max-w-md mb-8">
              Tải lên danh sách điểm theo định dạng STT, Họ tên, Lớp và các môn học để nhận báo cáo phân tích theo Thông tư 22.
            </p>
            <div className="bg-white p-6 rounded-2xl border border-dashed border-slate-300 max-w-lg w-full">
              <p className="text-sm font-medium text-slate-700 mb-4 text-left">Định dạng file yêu cầu:</p>
              <table className="w-full text-xs text-left border-collapse border border-slate-200 rounded overflow-hidden">
                <thead className="bg-slate-50">
                  <tr>
                    <th className="p-2 border border-slate-200">STT</th>
                    <th className="p-2 border border-slate-200">Họ tên</th>
                    <th className="p-2 border border-slate-200">Lớp</th>
                    <th className="p-2 border border-slate-200">Toán</th>
                    <th className="p-2 border border-slate-200">Văn</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td className="p-2 border border-slate-200">1</td>
                    <td className="p-2 border border-slate-200">Nguyễn Văn A</td>
                    <td className="p-2 border border-slate-200">10A1</td>
                    <td className="p-2 border border-slate-200">8.5</td>
                    <td className="p-2 border border-slate-200">7.2</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        ) : (
          <div className="space-y-8">
            {/* Dashboard Stats */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
              <StatCard title="Tổng số HS" value={stats.total} icon={<Users className="w-5 h-5" />} color="bg-slate-100 text-slate-700" />
              <StatCard title="Học sinh Tốt" value={stats.totCount} icon={<CheckCircle2 className="w-5 h-5" />} color="bg-emerald-100 text-emerald-700" />
              <StatCard title="Tiệm cận Tốt" value={stats.tiemCanTotCount} icon={<TrendingUp className="w-5 h-5" />} color="bg-blue-100 text-blue-700" />
              <StatCard title="Cần đầu tư" value={stats.datCount} icon={<HelpCircle className="w-5 h-5" />} color="bg-yellow-100 text-yellow-700" />
              <StatCard title="Nguy cơ/Chưa đạt" value={stats.nguyCoCount + stats.chuaDatCount} icon={<XCircle className="w-5 h-5" />} color="bg-rose-100 text-rose-700" />
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Analytics Section */}
              <div className="lg:col-span-2 space-y-6">
                <div className="bg-white p-6 rounded-2xl shadow-sm border">
                  <div className="flex items-center justify-between mb-6">
                    <h3 className="font-bold text-slate-900 flex items-center gap-2">
                      <BarChart3 className="w-5 h-5 text-indigo-600" /> Cấu trúc học lực lớp
                    </h3>
                  </div>
                  <div className="h-64">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData}>
                        <XAxis dataKey="name" fontSize={12} tickLine={false} axisLine={false} />
                        <YAxis fontSize={12} tickLine={false} axisLine={false} />
                        <Tooltip cursor={{fill: '#f1f5f9'}} contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)'}} />
                        <Bar dataKey="count" radius={[6, 6, 0, 0]}>
                          {chartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={entry.color} />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                <div className="bg-indigo-900 text-indigo-50 p-6 rounded-2xl shadow-lg relative overflow-hidden">
                  <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-3">
                      <Sparkles className="w-5 h-5 text-amber-300" />
                      <h3 className="font-bold">Gợi ý từ AI (Chiến lược sư phạm)</h3>
                    </div>
                    {aiAdvice ? (
                      <p className="text-sm leading-relaxed opacity-90">{aiAdvice}</p>
                    ) : (
                      <button 
                        onClick={loadAiAdvice}
                        className="px-4 py-2 bg-indigo-700 hover:bg-indigo-600 rounded-lg text-sm font-medium transition flex items-center gap-2"
                      >
                        <Sparkles className="w-4 h-4" /> Phân tích dữ liệu bằng AI
                      </button>
                    )}
                  </div>
                  <div className="absolute top-0 right-0 p-4 opacity-10">
                    <Sparkles className="w-24 h-24" />
                  </div>
                </div>
              </div>

              {/* Subject Breakdown Sidebar */}
              <div className="bg-white p-6 rounded-2xl shadow-sm border h-fit">
                <h3 className="font-bold text-slate-900 mb-4 flex items-center gap-2">
                  <Target className="w-5 h-5 text-indigo-600" /> Trọng tâm cải thiện
                </h3>
                <div className="space-y-4">
                  {headers.map(header => {
                    const avg = students.reduce((acc, s) => acc + s.scores.find(sc => sc.name === header)!.score, 0) / students.length;
                    return (
                      <div key={header}>
                        <div className="flex justify-between text-xs font-medium mb-1">
                          <span className="text-slate-600">{header}</span>
                          <span className="text-slate-900">{avg.toFixed(1)}</span>
                        </div>
                        <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                          <div 
                            className={`h-full transition-all duration-500 ${avg >= 8 ? 'bg-emerald-500' : avg >= 6.5 ? 'bg-blue-500' : 'bg-yellow-500'}`} 
                            style={{ width: `${avg * 10}%` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>

            {/* Student List Section */}
            <div className="bg-white rounded-2xl shadow-sm border overflow-hidden">
              <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h3 className="font-bold text-slate-900">Danh sách & Mục tiêu cá nhân</h3>
                <div className="flex flex-col sm:flex-row gap-2">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Tìm tên hoặc lớp..." 
                      className="pl-9 pr-4 py-2 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-64"
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                    />
                  </div>
                  <select 
                    className="px-4 py-2 border rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                    value={selectedClassification}
                    onChange={(e) => setSelectedClassification(e.target.value)}
                  >
                    <option value="All">Tất cả phân loại</option>
                    {Object.values(StudentClassification).map(val => (
                      <option key={val} value={val}>{val}</option>
                    ))}
                  </select>
                </div>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-50 text-slate-500 text-xs font-bold uppercase tracking-wider">
                      <th className="px-6 py-4">Họ tên & Lớp</th>
