import { SubjectLevel, StudentClassification, SubjectScore, StudentData, Goal } from './types';

export const getSubjectLevel = (score: number): SubjectLevel => {
  if (score >= 8.0) return SubjectLevel.TOT;
  if (score >= 6.5) return SubjectLevel.KHA;
  if (score >= 5.0) return SubjectLevel.DAT;
  return SubjectLevel.CHUA_DAT;
};

export const processRawStudentData = (
  raw: any, 
  subjectHeaders: string[],
  keys: { nameKey: string; classKey: string; sttKey: string }
): StudentData | null => {
  try {
    const scores: SubjectScore[] = subjectHeaders.map(header => {
      const val = raw[header];
      const score = typeof val === 'number' ? val : parseFloat(val);

      if (isNaN(score) || score < 0 || score > 10) {
        throw new Error(`Dữ liệu không hợp lệ ở môn ${header} cho học sinh ${raw[keys.nameKey]}`);
      }
      return {
        name: header,
        score,
        level: getSubjectLevel(score)
      };
    });

    const totCount = scores.filter(s => s.level === SubjectLevel.TOT).length;
    const khaCount = scores.filter(s => s.level === SubjectLevel.KHA).length;
    const datCount = scores.filter(s => s.level === SubjectLevel.DAT).length;
    const chuaDatCount = scores.filter(s => s.level === SubjectLevel.CHUA_DAT).length;
    const totalSubjects = scores.length;
    const totPercentage = (totCount / totalSubjects) * 100;

    let classification: StudentClassification = StudentClassification.CHUA_DAT;
    let summary = "";
    let goals: Goal[] = [];
    let prioritySubjects: string[] = [];

    // Decision Logic

    // 1. TOT
    if (totPercentage >= 80 && chuaDatCount === 0 && khaCount <= 1 && datCount === 0) {
      classification = StudentClassification.TOT;
      summary = "Duy trì và mở rộng năng lực vượt trội.";
    } 
    // 2. TIEM CAN TOT
    else if (totPercentage >= 60 && totPercentage < 80 && khaCount <= 2 && datCount === 0 && chuaDatCount === 0) {
      classification = StudentClassification.TIEM_CAN_TOT;
      summary = "Có tiềm năng lớn để đạt mức TỐT toàn diện.";
      const khaSubjects = scores.filter(s => s.level === SubjectLevel.KHA);
      goals = khaSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: Math.min(10, s.score + 0.6),
        increment: 0.6,
        description: "Mục tiêu nâng mức KHÁ lên TỐT."
      }));
      prioritySubjects = khaSubjects.map(s => s.name);
    }
    // 4. NGUY CO
    else if (scores.some(s => s.score >= 4.5 && s.score < 5.0) || scores.filter(s => s.score < 5.5).length >= 2) {
      classification = StudentClassification.NGUY_CO;
      summary = "Nguy cơ không đạt. Cần can thiệp hỗ trợ sớm.";
      const lowScores = [...scores].sort((a, b) => a.score - b.score).slice(0, 2);
      goals = lowScores.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Mục tiêu ngắn hạn: Vượt ngưỡng 5.0."
      }));
      prioritySubjects = lowScores.map(s => s.name);
    }
    // 5. CHUA DAT
    else if (chuaDatCount > 0) {
      classification = StudentClassification.CHUA_DAT;
      summary = "Chưa hoàn thành mục tiêu học tập tối thiểu.";
      const failedSubjects = scores.filter(s => s.level === SubjectLevel.CHUA_DAT);
      goals = failedSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Khoảng cách cần bù đắp để đạt mức tối thiểu."
      }));
      prioritySubjects = failedSubjects.map(s => s.name);
    }
    // 3. DAT
    else {
      classification = StudentClassification.DAT_CAN_DAU_TU;
      summary = "Đã đạt yêu cầu nhưng cần đầu tư thêm ở một số môn.";
      const lowDatSubjects = scores.filter(s => s.level === SubjectLevel.DAT).sort((a, b) => a.score - b.score);
      goals = lowDatSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 6.5,
        increment: 6.5 - s.score,
        description: "Mục tiêu nâng mức ĐẠT lên KHÁ."
      }));
      prioritySubjects = lowDatSubjects.map(s => s.name);
    }

    return {
      id: parseInt(raw[keys.sttKey]) || Math.floor(Math.random() * 10000),
      name: String(raw[keys.nameKey] || 'N/A').trim(),
      className: String(raw[keys.classKey] || 'N/A').trim(),
      scores,
      classification,
      summary,
      goals,
      prioritySubjects
    };
  } catch (err) {
    console.error("Error processing student:", err);
    return null;
  }
};

