            <div className="p-2 bg-indigo-600 rounded-lg">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 hidden sm:block">EduMind <span className="text-indigo-600 font-medium">TT22</span></h1>
          </div>
          <div className="flex items-center gap-4">
            {students.length > 0 && (
              <button 
                onClick={exportToExcel}
