import { SubjectLevel, StudentClassification, SubjectScore, StudentData, Goal } from './types';

export const getSubjectLevel = (score: number): SubjectLevel => {
  if (score >= 8.0) return SubjectLevel.TOT;
  if (score >= 6.5) return SubjectLevel.KHA;
  if (score >= 5.0) return SubjectLevel.DAT;
  return SubjectLevel.CHUA_DAT;
};

export const processRawStudentData = (
  raw: any, 
  subjectHeaders: string[],
  keys: { nameKey: string; classKey: string; sttKey: string }
): StudentData | null => {
  try {
    const scores: SubjectScore[] = subjectHeaders.map(header => {
      const val = raw[header];
      const score = typeof val === 'number' ? val : parseFloat(val);

      if (isNaN(score) || score < 0 || score > 10) {
        throw new Error(`Dữ liệu không hợp lệ ở môn ${header} cho học sinh ${raw[keys.nameKey]}`);
      }
      return {
        name: header,
        score,
        level: getSubjectLevel(score)
      };
    });

    const totCount = scores.filter(s => s.score >= 8.0).length;
    const minScore = scores.length > 0 ? Math.min(...scores.map(s => s.score)) : 0;

    let classification: StudentClassification = StudentClassification.DAT_CAN_DAU_TU;
    let summary = "";
    let goals: Goal[] = [];
    let prioritySubjects: string[] = [];

    // --- NEW LOGIC BASED ON USER REQUEST ---

    // 1. Học sinh Nguy cơ: có môn dưới 5.0
    if (minScore < 5.0) {
      classification = StudentClassification.NGUY_CO;
      summary = "Cảnh báo: Có môn dưới điểm trung bình. Cần hỗ trợ khẩn cấp.";
      const failedSubjects = scores.filter(s => s.score < 5.0);
      goals = failedSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Mục tiêu ngắn hạn: Đạt ngưỡng 5.0."
      }));
      prioritySubjects = failedSubjects.map(s => s.name);
    } 
    // 2. Học sinh Tốt: >= 6 môn >= 8.0 và không môn nào < 6.5
    else if (totCount >= 6 && minScore >= 6.5) {
      classification = StudentClassification.TOT;
      summary = "Duy trì phong độ và phát triển năng lực mũi nhọn.";
      // No specific goals needed for TOT, or maybe a stretch goal
      prioritySubjects = [];
    }
    // 3. Học sinh Tiệm cận Tốt: 
    // - Có 5 môn >= 8.0 và không môn nào < 6.5
    // - Hoặc đủ >= 6 môn >= 8.0 nhưng dính điều kiện có môn < 6.5
    else if ((totCount === 5 && minScore >= 6.5) || (totCount >= 6 && minScore < 6.5)) {
      classification = StudentClassification.TIEM_CAN_TOT;
      summary = "Tiềm năng đạt mức TỐT. Cần tập trung cải thiện các môn chưa đạt chuẩn 8.0 hoặc 6.5.";

      if (totCount >= 6 && minScore < 6.5) {
        // Goal is to pull up the subjects under 6.5
        const lowSubjects = scores.filter(s => s.score < 6.5);
        goals = lowSubjects.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 6.5,
          increment: 6.5 - s.score,
          description: "Nâng điểm để xóa bỏ điều kiện khống chế."
        }));
        prioritySubjects = lowSubjects.map(s => s.name);
      } else {
        // Goal is to pull the highest non-8.0 subject up to 8.0
        const potentialTot = scores.filter(s => s.score < 8.0).sort((a, b) => b.score - a.score).slice(0, 1);
        goals = potentialTot.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 8.0,
          increment: 8.0 - s.score,
          description: "Mục tiêu đạt môn thứ 6 ở mức TỐT."
        }));
        prioritySubjects = potentialTot.map(s => s.name);
      }
    }
    // 4. Học sinh Đạt: còn lại
    else {
      classification = StudentClassification.DAT_CAN_DAU_TU;
      summary = "Đã đạt yêu cầu nhưng cần nỗ lực nhiều hơn để vươn lên nhóm Khá/Tốt.";
      const lowestSubjects = [...scores].sort((a, b) => a.score - b.score).slice(0, 2);
      goals = lowestSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: Math.min(10, s.score + 1.0),
        increment: 1.0,
        description: "Mục tiêu cải thiện điểm số môn thấp điểm nhất."
      }));
      prioritySubjects = lowestSubjects.map(s => s.name);
    }

    return {
      id: parseInt(raw[keys.sttKey]) || Math.floor(Math.random() * 10000),
      name: String(raw[keys.nameKey] || 'N/A').trim(),
      className: String(raw[keys.classKey] || 'N/A').trim(),
      scores,
      classification,
      summary,
      goals,
      prioritySubjects
    };
  } catch (err) {
    console.error("Error processing student:", err);
    return null;
  }
};

export enum SubjectLevel {
  TOT = 'TỐT',
  KHA = 'KHÁ',
  DAT = 'ĐẠT',
  CHUA_DAT = 'CHƯA ĐẠT'
}

export enum StudentClassification {
  TOT = 'Học sinh TỐT',
  TIEM_CAN_TOT = 'Tiệm cận TỐT',
  KHA = 'Học sinh KHÁ',
  DAT = 'Học sinh ĐẠT',
  NGUY_CO = 'Nguy cơ (Dưới 5.0)',
}

export interface SubjectScore {
  name: string;
  score: number;
  level: SubjectLevel;
}

export interface Goal {
  subjectName: string;
  currentScore: number;
  targetScore: number;
  increment: number;
  description: string;
}

export interface StudentData {
  id: number;
  name: string;
  className: string;
  scores: SubjectScore[];
  classification: StudentClassification;
  summary: string;
  goals: Goal[];
  prioritySubjects: string[];
}

export interface ClassStats {
  total: number;
  totCount: number;
  tiemCanTotCount: number;
  khaCount: number;
  datCount: number;
  nguyCoCount: number;
}

import { SubjectLevel, StudentClassification, SubjectScore, StudentData, Goal } from './types';

export const getSubjectLevel = (score: number): SubjectLevel => {
  if (score >= 8.0) return SubjectLevel.TOT;
  if (score >= 6.5) return SubjectLevel.KHA;
  if (score >= 5.0) return SubjectLevel.DAT;
  return SubjectLevel.CHUA_DAT;
};

export const processRawStudentData = (
  raw: any, 
  subjectHeaders: string[],
  keys: { nameKey: string; classKey: string; sttKey: string }
): StudentData | null => {
  try {
    const scores: SubjectScore[] = subjectHeaders.map(header => {
      const val = raw[header];
      const score = typeof val === 'number' ? val : parseFloat(val);

      if (isNaN(score) || score < 0 || score > 10) {
        throw new Error(`Dữ liệu không hợp lệ ở môn ${header} cho học sinh ${raw[keys.nameKey]}`);
      }
      return {
        name: header,
        score,
        level: getSubjectLevel(score)
      };
    });

    const totCount = scores.filter(s => s.score >= 8.0).length;
    const khaPlusCount = scores.filter(s => s.score >= 6.5).length;
    const minScore = scores.length > 0 ? Math.min(...scores.map(s => s.score)) : 0;

    let classification: StudentClassification = StudentClassification.DAT;
    let summary = "";
    let goals: Goal[] = [];
    let prioritySubjects: string[] = [];

    // --- UPDATED LOGIC BASED ON NEW REQUIREMENTS ---

    // 1. Học sinh Nguy cơ: có môn dưới 5.0
    if (minScore < 5.0) {
      classification = StudentClassification.NGUY_CO;
      summary = "Cảnh báo: Có ít nhất một môn dưới 5.0. Cần hỗ trợ khẩn cấp để đạt điểm trung bình.";
      const failedSubjects = scores.filter(s => s.score < 5.0);
      goals = failedSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Mục tiêu ngắn hạn: Vượt ngưỡng 5.0."
      }));
      prioritySubjects = failedSubjects.map(s => s.name);
    } 
    // 2. Học sinh Tốt: 6+ môn >= 8.0 and no subject < 6.5
    else if (totCount >= 6 && minScore >= 6.5) {
      classification = StudentClassification.TOT;
      summary = "Duy trì phong độ xuất sắc và phát triển các môn thế mạnh.";
      prioritySubjects = [];
    }
    // 3. Học sinh Tiệm cận Tốt: 
    // - 5 môn >= 8.0 and no subject < 6.5
    // - OR 6+ môn >= 8.0 but has subject < 6.5 (all must be >= 5.0 already checked)
    else if ((totCount === 5 && minScore >= 6.5) || (totCount >= 6 && minScore < 6.5)) {
      classification = StudentClassification.TIEM_CAN_TOT;
      summary = "Tiềm năng đạt mức TỐT rất cao. Cần nâng điểm các môn vướng điều kiện khống chế.";

      if (totCount >= 6 && minScore < 6.5) {
        const constraintSubjects = scores.filter(s => s.score < 6.5);
        goals = constraintSubjects.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 6.5,
          increment: 6.5 - s.score,
          description: "Mục tiêu đạt 6.5 để xóa bỏ điểm khống chế."
        }));
        prioritySubjects = constraintSubjects.map(s => s.name);
      } else {
        const topNonTot = scores.filter(s => s.score < 8.0).sort((a, b) => b.score - a.score).slice(0, 1);
        goals = topNonTot.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 8.0,
          increment: 8.0 - s.score,
          description: "Nâng điểm môn này lên 8.0 để đạt chuẩn TỐT."
        }));
        prioritySubjects = topNonTot.map(s => s.name);
      }
    }
    // 4. Học sinh Khá: Tất cả > 5.0 và có 6+ môn >= 6.5
    else if (minScore >= 5.0 && khaPlusCount >= 6) {
      classification = StudentClassification.KHA;
      summary = "Năng lực khá. Tập trung bồi dưỡng các môn cận 8.0 để tiến tới Tiệm cận Tốt.";
      const nearTot = scores.filter(s => s.score < 8.0 && s.score >= 7.0).sort((a, b) => b.score - a.score).slice(0, 2);
      goals = nearTot.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 8.0,
        increment: 8.0 - s.score,
        description: "Mục tiêu nâng lên mức Tốt cho môn học này."
      }));
      prioritySubjects = nearTot.map(s => s.name);
    }
    // 5. Học sinh Đạt: All >= 5.0 but not Khá
    else {
      classification = StudentClassification.DAT;
      summary = "Học lực trung bình. Cần nỗ lực cải thiện để đạt mức Khá.";
      const lowKha = scores.filter(s => s.score < 6.5).sort((a, b) => a.score - b.score).slice(0, 2);
      goals = lowKha.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 6.5,
        increment: 6.5 - s.score,
        description: "Mục tiêu đạt 6.5 để tiến tới xếp loại Khá."
      }));
      prioritySubjects = lowKha.map(s => s.name);
    }

    return {
      id: parseInt(raw[keys.sttKey]) || Math.floor(Math.random() * 10000),
      name: String(raw[keys.nameKey] || 'N/A').trim(),
      className: String(raw[keys.classKey] || 'N/A').trim(),
      scores,
      classification,
      summary,
      goals,
      prioritySubjects
    };
  } catch (err) {
    console.error("Error processing student:", err);
    return null;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  Upload, 
  FileText, 
  Download, 
  AlertCircle, 
  TrendingUp, 
  Target, 
  Users, 
  ChevronRight,
  Sparkles,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  BarChart3,
  Award
} from 'lucide-react';
import { StudentData, ClassStats, StudentClassification } from './types';
import { processRawStudentData } from './gradingService';
import { getPedagogicalAdvice } from './geminiService';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';

const App: React.FC = () => {
  const [students, setStudents] = useState<StudentData[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedClassification, setSelectedClassification] = useState<string>("All");

  const stats = useMemo((): ClassStats => {
    return {
      total: students.length,
      totCount: students.filter(s => s.classification === StudentClassification.TOT).length,
      tiemCanTotCount: students.filter(s => s.classification === StudentClassification.TIEM_CAN_TOT).length,
      khaCount: students.filter(s => s.classification === StudentClassification.KHA).length,
      datCount: students.filter(s => s.classification === StudentClassification.DAT).length,
      nguyCoCount: students.filter(s => s.classification === StudentClassification.NGUY_CO).length,
    };
  }, [students]);

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const name = s.name || "";
      const className = s.className || "";
      const matchesSearch = name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            className.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = selectedClassification === "All" || s.classification === selectedClassification;
      return matchesSearch && matchesFilter;
    });
  }, [students, searchTerm, selectedClassification]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json<any>(ws);

        if (data.length === 0) {
          throw new Error("File trống hoặc sai định dạng.");
        }

        const allHeaders = Object.keys(data[0]);

        // Smart header detection
        const nameKey = allHeaders.find(h => {
          const lower = h.trim().toLowerCase();
          return lower === 'họ tên' || lower === 'họ và tên' || lower === 'tên' || (lower.includes('họ') && lower.includes('tên'));
        }) || 'Họ tên';

        const classKey = allHeaders.find(h => {
          const lower = h.trim().toLowerCase();
          return lower === 'lớp' || lower.includes('lớp');
        }) || 'Lớp';

        const sttKey = allHeaders.find(h => {
          const lower = h.trim().toLowerCase();
          return lower === 'stt' || lower === 'số thứ tự';
        }) || 'STT';

        const subjectHeaders = allHeaders.filter(h => 
          ![sttKey, nameKey, classKey].includes(h)
        );

        setHeaders(subjectHeaders);

        const keys = { nameKey, classKey, sttKey };
        const processed = data.map(item => processRawStudentData(item, subjectHeaders, keys))
                             .filter((s): s is StudentData => s !== null);

        if (processed.length === 0) {
          throw new Error("Không thể xử lý dữ liệu học sinh. Vui lòng kiểm tra lại tiêu đề cột (Họ tên, Lớp, STT).");
        }

        setStudents(processed);
      } catch (err: any) {
        setError(err.message || "Lỗi khi xử lý file Excel.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const loadAiAdvice = async () => {
    if (students.length === 0) return;
    setAiAdvice("Đang phân tích dữ liệu...");
    const advice = await getPedagogicalAdvice(stats, students);
    setAiAdvice(advice);
  };

  const exportToExcel = () => {
    const dataToExport = students.map(s => ({
      'STT': s.id,
      'Họ tên': s.name,
      'Lớp': s.className,
      'Phân loại': s.classification,
      'Ghi chú': s.summary,
      'Môn trọng tâm': s.prioritySubjects.join(', '),
      'Mục tiêu tiến bộ': s.goals.map(g => `${g.subjectName} -> ${g.targetScore.toFixed(1)}`).join('; ')
    }));
    const ws = XLSX.utils.json_to_sheet(dataToExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Báo cáo");
    XLSX.writeFile(wb, "Bao_cao_hoc_sinh.xlsx");
  };

  const getClassificationColor = (cls: StudentClassification) => {
    switch (cls) {
      case StudentClassification.TOT: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case StudentClassification.TIEM_CAN_TOT: return 'bg-blue-100 text-blue-700 border-blue-200';
      case StudentClassification.KHA: return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case StudentClassification.DAT: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
      case StudentClassification.NGUY_CO: return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const chartData = [
    { name: 'Tốt', count: stats.totCount, color: '#10b981' },
    { name: 'Tiệm cận Tốt', count: stats.tiemCanTotCount, color: '#3b82f6' },
    { name: 'Khá', count: stats.khaCount, color: '#6366f1' },
    { name: 'Đạt', count: stats.datCount, color: '#eab308' },
