import { GoogleGenAI } from "@google/genai";
import { StudentData, ClassStats } from "./types";

export const getPedagogicalAdvice = async (stats: ClassStats, students: StudentData[]): Promise<string> => {
  try {
    // Create a new GoogleGenAI instance right before making an API call to ensure it always uses the most up-to-date API key.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Fixed: stats.chuaDatCount does not exist on ClassStats. Included stats.khaCount for better context.
    const prompt = `
      Dưới đây là thống kê kết quả học tập của một lớp:
      - Tổng số học sinh: ${stats.total}
      - Tốt: ${stats.totCount}
      - Tiệm cận Tốt: ${stats.tiemCanTotCount}
      - Khá: ${stats.khaCount}
      - Đạt (Cần đầu tư): ${stats.datCount}
      - Nguy cơ: ${stats.nguyCoCount}

      Hãy đóng vai một chuyên gia tư vấn giáo dục, phân tích tình hình và đưa ra 3 lời khuyên chiến lược cho giáo viên chủ nhiệm để cải thiện chất lượng học tập trong học kỳ tới. Viết ngắn gọn, súc tích bằng tiếng Việt.
    `;

    // Using gemini-3-flash-preview for summarization and analysis tasks.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    // Directly access the .text property of GenerateContentResponse.
    return response.text || "Không thể tải lời khuyên từ AI.";
  } catch (error) {
    console.error("Error fetching AI advice:", error);
    return "Hãy tập trung hỗ trợ nhóm học sinh nguy cơ và bồi dưỡng nhóm tiệm cận tốt.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  Upload, 
  FileText, 
  Download, 
  AlertCircle, 
  TrendingUp, 
  Target, 
  Users, 
  ChevronRight,
  Sparkles,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  BarChart3,
  Award,
  Grid,
  Filter,
  Layers
} from 'lucide-react';
import { StudentData, ClassStats, StudentClassification } from './types';
import { processRawStudentData } from './gradingService';
import { getPedagogicalAdvice } from './geminiService';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';

const App: React.FC = () => {
  const [students, setStudents] = useState<StudentData[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedClassification, setSelectedClassification] = useState<string>("All");
  const [activeClass, setActiveClass] = useState<string>("Tất cả");

  // Group students by class
  const classGroups = useMemo(() => {
    const groups: Record<string, StudentData[]> = { "Tất cả": students };
    students.forEach(s => {
      const cls = s.className || "Chưa phân lớp";
      if (!groups[cls]) groups[cls] = [];
      groups[cls].push(s);
    });
    return groups;
  }, [students]);

  const classNames = useMemo(() => Object.keys(classGroups).sort(), [classGroups]);

  // Students to display based on filters
  const displayStudents = useMemo(() => {
    let list = classGroups[activeClass] || [];

    return list.filter(s => {
      const name = s.name || "";
      const className = s.className || "";
      const matchesSearch = name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            className.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = selectedClassification === "All" || s.classification === selectedClassification;
      return matchesSearch && matchesFilter;
    });
  }, [classGroups, activeClass, searchTerm, selectedClassification]);

  const stats = useMemo((): ClassStats => {
    const list = displayStudents;
    return {
      total: list.length,
      totCount: list.filter(s => s.classification === StudentClassification.TOT).length,
      tiemCanTotCount: list.filter(s => s.classification === StudentClassification.TIEM_CAN_TOT).length,
      khaCount: list.filter(s => s.classification === StudentClassification.KHA).length,
      datCount: list.filter(s => s.classification === StudentClassification.DAT).length,
      nguyCoCount: list.filter(s => s.classification === StudentClassification.NGUY_CO).length,
    };
  }, [displayStudents]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });

        let allProcessedStudents: StudentData[] = [];
        let allSubjectHeaders: Set<string> = new Set();

        // Process ALL sheets in the workbook
        wb.SheetNames.forEach(wsname => {
          const ws = wb.Sheets[wsname];
          const data = XLSX.utils.sheet_to_json<any>(ws);

          if (data.length === 0) return;

          const allHeaders = Object.keys(data[0]);

          // Smart header detection
          const nameKey = allHeaders.find(h => {
            const lower = h.trim().toLowerCase();
            return ['họ tên', 'họ và tên', 'tên', 'fullname', 'name'].includes(lower) || (lower.includes('họ') && lower.includes('tên'));
          }) || 'Họ tên';

          const classKey = allHeaders.find(h => {
            const lower = h.trim().toLowerCase();
            return ['lớp', 'class', 'grade'].includes(lower) || lower.includes('lớp');
          }) || 'Lớp';

          const sttKey = allHeaders.find(h => {
            const lower = h.trim().toLowerCase();
            return ['stt', 'số thứ tự', 'id', 'no'].includes(lower);
          }) || 'STT';

          const subjectHeaders = allHeaders.filter(h => 
            ![sttKey, nameKey, classKey].includes(h)
          );

          subjectHeaders.forEach(h => allSubjectHeaders.add(h));

          const keys = { nameKey, classKey, sttKey };
          const processed = data.map(item => {
            // If class name is missing in row, use sheet name
            if (!item[classKey]) item[classKey] = wsname;
            return processRawStudentData(item, subjectHeaders, keys);
          }).filter((s): s is StudentData => s !== null);

          allProcessedStudents = [...allProcessedStudents, ...processed];
        });

        if (allProcessedStudents.length === 0) {
          throw new Error("Không thể xử lý dữ liệu. Vui lòng kiểm tra định dạng file (Cột Họ tên, Lớp, và Điểm số).");
        }

        setHeaders(Array.from(allSubjectHeaders));
        setStudents(allProcessedStudents);
        setActiveClass("Tất cả");
      } catch (err: any) {
        setError(err.message || "Lỗi khi xử lý file Excel.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const loadAiAdvice = async () => {
    if (displayStudents.length === 0) return;
    setAiAdvice("Đang phân tích dữ liệu...");
    const advice = await getPedagogicalAdvice(stats, displayStudents);
    setAiAdvice(advice);
  };

  const exportToExcel = () => {
    const dataToExport = displayStudents.map(s => ({
      'STT': s.id,
      'Họ tên': s.name,
      'Lớp': s.className,
      'Phân loại': s.classification,
      'Ghi chú': s.summary,
      'Môn trọng tâm': s.prioritySubjects.join(', '),
      'Mục tiêu tiến bộ': s.goals.map(g => `${g.subjectName} -> ${g.targetScore.toFixed(1)}`).join('; ')
    }));
    const ws = XLSX.utils.json_to_sheet(dataToExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Báo cáo");
    XLSX.writeFile(wb, `Bao_cao_${activeClass.replace(/\s/g, '_')}.xlsx`);
  };

  const getClassificationColor = (cls: StudentClassification) => {
    switch (cls) {
      case StudentClassification.TOT: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case StudentClassification.TIEM_CAN_TOT: return 'bg-blue-100 text-blue-700 border-blue-200';
      case StudentClassification.KHA: return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case StudentClassification.DAT: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
      case StudentClassification.NGUY_CO: return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const chartData = [
    { name: 'Tốt', count: stats.totCount, color: '#10b981' },
