import { SubjectLevel, StudentClassification, SubjectScore, StudentData, Goal } from './types';

export const getSubjectLevel = (score: number): SubjectLevel => {
  if (score >= 8.0) return SubjectLevel.TOT;
  if (score >= 6.5) return SubjectLevel.KHA;
  if (score >= 5.0) return SubjectLevel.DAT;
  return SubjectLevel.CHUA_DAT;
};

export const processRawStudentData = (
  raw: any, 
  subjectHeaders: string[],
  keys: { nameKey: string; classKey: string; sttKey: string }
): StudentData | null => {
  try {
    const scores: SubjectScore[] = subjectHeaders.map(header => {
      const val = raw[header];
      const score = typeof val === 'number' ? val : parseFloat(val);

      if (isNaN(score) || score < 0 || score > 10) {
        // Skip invalid scores but log for safety
        return { name: header, score: 0, level: SubjectLevel.CHUA_DAT };
      }
      return {
        name: header,
        score,
        level: getSubjectLevel(score)
      };
    });

    const totCount = scores.filter(s => s.score >= 8.0).length;
    const khaPlusCount = scores.filter(s => s.score >= 6.5).length;
    const validScores = scores.filter(s => !isNaN(s.score));
    const minScore = validScores.length > 0 ? Math.min(...validScores.map(s => s.score)) : 0;

    let classification: StudentClassification = StudentClassification.DAT;
    let summary = "";
    let goals: Goal[] = [];
    let prioritySubjects: string[] = [];

    // --- LOGIC TT22 REFINED ---

    // 1. Học sinh Nguy cơ: có môn dưới 5.0
    if (minScore < 5.0) {
      classification = StudentClassification.NGUY_CO;
      summary = "Cảnh báo: Có ít nhất một môn dưới 5.0. Cần hỗ trợ khẩn cấp để đạt điểm trung bình.";
      const failedSubjects = scores.filter(s => s.score < 5.0);
      goals = failedSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Mục tiêu ngắn hạn: Vượt ngưỡng 5.0."
      }));
      prioritySubjects = failedSubjects.map(s => s.name);
    } 
    // 2. Học sinh Tốt: 6+ môn >= 8.0 and no subject < 6.5
    else if (totCount >= 6 && minScore >= 6.5) {
      classification = StudentClassification.TOT;
      summary = "Duy trì phong độ xuất sắc và phát triển các môn thế mạnh.";
      prioritySubjects = [];
    }
    // 3. Học sinh Tiệm cận Tốt: 
    // - 5 môn >= 8.0 and no subject < 6.5
    // - OR 6+ môn >= 8.0 but has subject < 6.5
    else if ((totCount === 5 && minScore >= 6.5) || (totCount >= 6 && minScore < 6.5)) {
      classification = StudentClassification.TIEM_CAN_TOT;
      summary = "Tiềm năng đạt mức TỐT rất cao. Cần nâng điểm các môn vướng điều kiện khống chế.";

      if (totCount >= 6 && minScore < 6.5) {
        const constraintSubjects = scores.filter(s => s.score < 6.5);
        goals = constraintSubjects.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 6.5,
          increment: 6.5 - s.score,
          description: "Mục tiêu đạt 6.5 để xóa bỏ điểm khống chế."
        }));
        prioritySubjects = constraintSubjects.map(s => s.name);
      } else {
        const topNonTot = scores.filter(s => s.score < 8.0).sort((a, b) => b.score - a.score).slice(0, 1);
        goals = topNonTot.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 8.0,
          increment: 8.0 - s.score,
          description: "Nâng điểm môn này lên 8.0 để đạt chuẩn TỐT."
        }));
        prioritySubjects = topNonTot.map(s => s.name);
      }
    }
    // 4. Học sinh Khá: Tất cả > 5.0 và có 6+ môn >= 6.5
    else if (minScore >= 5.0 && khaPlusCount >= 6) {
      classification = StudentClassification.KHA;
      summary = "Năng lực khá. Tập trung bồi dưỡng các môn cận 8.0 để tiến tới Tiệm cận Tốt.";
      const nearTot = scores.filter(s => s.score < 8.0 && s.score >= 7.0).sort((a, b) => b.score - a.score).slice(0, 2);
      goals = nearTot.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 8.0,
        increment: 8.0 - s.score,
        description: "Mục tiêu nâng lên mức Tốt cho môn học này."
      }));
      prioritySubjects = nearTot.map(s => s.name);
    }
    // 5. Học sinh Đạt: All >= 5.0 but not Khá
    else {
      classification = StudentClassification.DAT;
      summary = "Học lực trung bình. Cần nỗ lực cải thiện để đạt mức Khá.";
      const lowKha = scores.filter(s => s.score < 6.5).sort((a, b) => a.score - b.score).slice(0, 2);
      goals = lowKha.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 6.5,
        increment: 6.5 - s.score,
        description: "Mục tiêu đạt 6.5 để tiến tới xếp loại Khá."
      }));
      prioritySubjects = lowKha.map(s => s.name);
    }

    const name = String(raw[keys.nameKey] || 'N/A').trim();
    const className = String(raw[keys.classKey] || 'N/A').trim();
    const idValue = parseInt(raw[keys.sttKey]);

    return {
      id: isNaN(idValue) ? Math.floor(Math.random() * 1000000) : idValue,
      name,
      className,
      scores,
      classification,
      summary,
      goals,
      prioritySubjects
    };
  } catch (err) {
    console.error("Error processing student:", err);
    return null;
  }
};

import { SubjectLevel, StudentClassification, SubjectScore, StudentData, Goal } from './types';

export const getSubjectLevel = (score: number): SubjectLevel => {
  if (score >= 8.0) return SubjectLevel.TOT;
  if (score >= 6.5) return SubjectLevel.KHA;
  if (score >= 5.0) return SubjectLevel.DAT;
  return SubjectLevel.CHUA_DAT;
};

export const processRawStudentData = (
  raw: any, 
  subjectHeaders: string[],
  keys: { nameKey: string; classKey: string; sttKey: string }
): StudentData | null => {
  try {
    const name = String(raw[keys.nameKey] || '').trim();
    // Nếu không có tên, đây là dòng trống hoặc dòng rác
    if (!name || name.toLowerCase() === 'họ tên' || name.length < 2) {
      return null;
    }

    let hasValidScore = false;
    const scores: SubjectScore[] = subjectHeaders.map(header => {
      const val = raw[header];
      let score = typeof val === 'number' ? val : parseFloat(val);

      if (isNaN(score)) {
        return { name: header, score: -1, level: SubjectLevel.CHUA_DAT };
      }

      hasValidScore = true;
      return {
        name: header,
        score,
        level: getSubjectLevel(score)
      };
    }).filter(s => s.score !== -1);

    // Nếu dòng có tên nhưng không có bất kỳ điểm số nào hợp lệ, bỏ qua
    if (!hasValidScore || scores.length === 0) {
      return null;
    }

    const totCount = scores.filter(s => s.score >= 8.0).length;
    const khaPlusCount = scores.filter(s => s.score >= 6.5).length;
    const minScore = Math.min(...scores.map(s => s.score));

    let classification: StudentClassification = StudentClassification.DAT;
    let summary = "";
    let goals: Goal[] = [];
    let prioritySubjects: string[] = [];

    // --- LOGIC PHÂN LOẠI TT22 ---

    // 1. Học sinh Nguy cơ: có môn dưới 5.0
    if (minScore < 5.0) {
      classification = StudentClassification.NGUY_CO;
      summary = "Cần hỗ trợ khẩn cấp để đạt điểm trung bình (5.0).";
      const failedSubjects = scores.filter(s => s.score < 5.0);
      goals = failedSubjects.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Mục tiêu vượt ngưỡng 5.0."
      }));
      prioritySubjects = failedSubjects.map(s => s.name);
    } 
    // 2. Học sinh Tốt: 6+ môn >= 8.0 và không môn nào < 6.5
    else if (totCount >= 6 && minScore >= 6.5) {
      classification = StudentClassification.TOT;
      summary = "Duy trì phong độ xuất sắc.";
      prioritySubjects = [];
    }
    // 3. Học sinh Tiệm cận Tốt: 
    // - 5 môn >= 8.0 và không môn nào < 6.5
    // - HOẶC 6+ môn >= 8.0 nhưng có môn < 6.5
    else if ((totCount === 5 && minScore >= 6.5) || (totCount >= 6 && minScore < 6.5)) {
      classification = StudentClassification.TIEM_CAN_TOT;
      summary = "Tiềm năng đạt mức TỐT. Cần nâng điểm các môn chưa đạt chuẩn.";

      if (totCount >= 6 && minScore < 6.5) {
        const constraintSubjects = scores.filter(s => s.score < 6.5);
        goals = constraintSubjects.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 6.5,
          increment: 6.5 - s.score,
          description: "Mục tiêu đạt 6.5 để đạt loại TỐT."
        }));
        prioritySubjects = constraintSubjects.map(s => s.name);
      } else {
        const topNonTot = scores.filter(s => s.score < 8.0).sort((a, b) => b.score - a.score).slice(0, 1);
        goals = topNonTot.map(s => ({
          subjectName: s.name,
          currentScore: s.score,
          targetScore: 8.0,
          increment: 8.0 - s.score,
          description: "Nâng lên 8.0 để đạt chuẩn TỐT môn thứ 6."
        }));
        prioritySubjects = topNonTot.map(s => s.name);
      }
    }
    // 4. Học sinh Khá: Tất cả > 5.0 và có 6+ môn >= 6.5
    else if (minScore >= 5.0 && khaPlusCount >= 6) {
      classification = StudentClassification.KHA;
      summary = "Năng lực Khá. Cải thiện các môn cận 8.0.";
      const nearTot = scores.filter(s => s.score < 8.0 && s.score >= 7.0).sort((a, b) => b.score - a.score).slice(0, 2);
      goals = nearTot.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 8.0,
        increment: 8.0 - s.score,
        description: "Mục tiêu nâng lên mức Tốt."
      }));
      prioritySubjects = nearTot.map(s => s.name);
    }
    // 5. Học sinh Đạt: Còn lại
    else {
      classification = StudentClassification.DAT;
      summary = "Học lực trung bình. Cần nỗ lực để đạt mức Khá.";
      const lowKha = scores.filter(s => s.score < 6.5).sort((a, b) => a.score - b.score).slice(0, 2);
      goals = lowKha.map(s => ({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 6.5,
        increment: 6.5 - s.score,
        description: "Mục tiêu đạt chuẩn 6.5."
      }));
      prioritySubjects = lowKha.map(s => s.name);
    }

    const className = String(raw[keys.classKey] || 'Chưa rõ').trim();
    const idValue = parseInt(raw[keys.sttKey]);

    return {
      id: isNaN(idValue) ? Math.floor(Math.random() * 1000000) : idValue,
      name,
      className,
      scores,
      classification,
      summary,
      goals,
      prioritySubjects
    };
  } catch (err) {
    return null;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  Upload, 
  FileText, 
  Download, 
  AlertCircle, 
  TrendingUp, 
  Target, 
  Users, 
  ChevronRight,
  Sparkles,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  BarChart3,
  Award,
  Grid,
  Filter,
  Layers
} from 'lucide-react';
import { StudentData, ClassStats, StudentClassification } from './types';
import { processRawStudentData } from './gradingService';
import { getPedagogicalAdvice } from './geminiService';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  ResponsiveContainer, 
  Cell
} from 'recharts';

const App: React.FC = () => {
  const [students, setStudents] = useState<StudentData[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [aiAdvice, setAiAdvice] = useState<string>("");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedClassification, setSelectedClassification] = useState<string>("All");
  const [activeClass, setActiveClass] = useState<string>("Tất cả");

  // Group students by class
  const classGroups = useMemo(() => {
    const groups: Record<string, StudentData[]> = { "Tất cả": students };
    students.forEach(s => {
      const cls = s.className || "Chưa rõ";
      if (!groups[cls]) groups[cls] = [];
      groups[cls].push(s);
    });
    return groups;
  }, [students]);

  const classNames = useMemo(() => Object.keys(classGroups).sort(), [classGroups]);

  // Display students based on filters
  const displayStudents = useMemo(() => {
    let list = classGroups[activeClass] || [];

    return list.filter(s => {
      const name = s.name || "";
      const matchesSearch = name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = selectedClassification === "All" || s.classification === selectedClassification;
      return matchesSearch && matchesFilter;
    });
  }, [classGroups, activeClass, searchTerm, selectedClassification]);

  const stats = useMemo((): ClassStats => {
    const list = displayStudents;
    return {
      total: list.length,
      totCount: list.filter(s => s.classification === StudentClassification.TOT).length,
      tiemCanTotCount: list.filter(s => s.classification === StudentClassification.TIEM_CAN_TOT).length,
      khaCount: list.filter(s => s.classification === StudentClassification.KHA).length,
      datCount: list.filter(s => s.classification === StudentClassification.DAT).length,
      nguyCoCount: list.filter(s => s.classification === StudentClassification.NGUY_CO).length,
    };
  }, [displayStudents]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    setAiAdvice("");
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });

        let allProcessedStudents: StudentData[] = [];
        let allSubjectHeaders: Set<string> = new Set();

        wb.SheetNames.forEach(wsname => {
          const ws = wb.Sheets[wsname];
          // Chuyển đổi với blankrows: false để loại bỏ dòng trống cấp độ thư viện
          const data = XLSX.utils.sheet_to_json<any>(ws, { blankrows: false });

          if (data.length === 0) return;

          const allHeaders = Object.keys(data[0]);

          const nameKey = allHeaders.find(h => {
            const l = h.trim().toLowerCase();
            return ['họ tên', 'họ và tên', 'tên', 'name', 'fullname'].includes(l) || (l.includes('họ') && l.includes('tên'));
          }) || 'Họ tên';

          const classKey = allHeaders.find(h => {
            const l = h.trim().toLowerCase();
            return ['lớp', 'class', 'grade'].includes(l) || l.includes('lớp');
          }) || 'Lớp';

          const sttKey = allHeaders.find(h => {
            const l = h.trim().toLowerCase();
            return ['stt', 'số thứ tự', 'id', 'no'].includes(l);
          }) || 'STT';

          const subjectHeaders = allHeaders.filter(h => 
            ![sttKey, nameKey, classKey].includes(h)
          );

          subjectHeaders.forEach(h => allSubjectHeaders.add(h));

          const keys = { nameKey, classKey, sttKey };
          const processed = data.map(item => {
            // Ưu tiên lớp trong cột dữ liệu, nếu không có mới dùng tên Sheet
            if (!item[classKey]) item[classKey] = wsname;
            return processRawStudentData(item, subjectHeaders, keys);
          }).filter((s): s is StudentData => s !== null);

          allProcessedStudents = [...allProcessedStudents, ...processed];
        });

        if (allProcessedStudents.length === 0) {
          throw new Error("Không tìm thấy dữ liệu học sinh hợp lệ. Vui lòng kiểm tra cột Họ tên và Điểm số.");
        }

        setHeaders(Array.from(allSubjectHeaders));
        setStudents(allProcessedStudents);
        setActiveClass("Tất cả");
      } catch (err: any) {
        setError(err.message || "Lỗi khi xử lý file Excel.");
      } finally {
        setLoading(false);
      }
    };

    reader.readAsBinaryString(file);
  };

  const loadAiAdvice = async () => {
    if (displayStudents.length === 0) return;
    setAiAdvice("Đang phân tích dữ liệu...");
    const advice = await getPedagogicalAdvice(stats, displayStudents);
    setAiAdvice(advice);
  };

  const exportToExcel = () => {
    const dataToExport = displayStudents.map(s => ({
      'STT': s.id,
      'Họ tên': s.name,
      'Lớp': s.className,
      'Phân loại': s.classification,
      'Ghi chú': s.summary,
      'Môn trọng tâm': s.prioritySubjects.join(', '),
      'Mục tiêu tiến bộ': s.goals.map(g => `${g.subjectName} -> ${g.targetScore.toFixed(1)}`).join('; ')
    }));
    const ws = XLSX.utils.json_to_sheet(dataToExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Báo cáo");
    XLSX.writeFile(wb, `Bao_cao_${activeClass.replace(/\s/g, '_')}.xlsx`);
  };

  const getClassificationColor = (cls: StudentClassification) => {
    switch (cls) {
      case StudentClassification.TOT: return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case StudentClassification.TIEM_CAN_TOT: return 'bg-blue-100 text-blue-700 border-blue-200';
      case StudentClassification.KHA: return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case StudentClassification.DAT: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
      case StudentClassification.NGUY_CO: return 'bg-rose-100 text-rose-700 border-rose-200';
      default: return 'bg-slate-100 text-slate-700 border-slate-200';
    }
  };

  const chartData = [
    { name: 'Tốt', count: stats.totCount, color: '#10b981' },
    { name: 'Tiệm cận Tốt', count: stats.tiemCanTotCount, color: '#3b82f6' },
    { name: 'Khá', count: stats.khaCount, color: '#6366f1' },
    { name: 'Đạt', count: stats.datCount, color: '#eab308' },
    { name: 'Nguy cơ', count: stats.nguyCoCount, color: '#f43f5e' },
  ];

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-white border-b sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="p-2 bg-indigo-600 rounded-lg shadow-sm">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-bold text-slate-900 leading-none">EduMind</h1>
              <span className="text-[10px] text-indigo-600 font-bold uppercase tracking-wider">TT22 Support System</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            {students.length > 0 && (
              <button 
                onClick={exportToExcel}
                className="flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-200 text-slate-700 rounded-lg hover:bg-slate-50 transition text-sm font-medium shadow-sm"
              >
                <Download className="w-4 h-4" /> <span className="hidden sm:inline">Xuất Excel</span>
              </button>
            )}
            <label className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition text-sm font-medium shadow-md">
              <Upload className="w-4 h-4" /> {students.length === 0 ? "Tải file Excel" : "Cập nhật dữ liệu"}
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 w-full">
        {loading && (
          <div className="mb-6 p-4 bg-indigo-50 border border-indigo-200 text-indigo-700 rounded-xl flex items-center gap-3">
             <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
             <p className="text-sm font-medium">Đang chuẩn hóa dữ liệu học sinh...</p>
