                <div className="space-y-4">
                  {headers.map(header => {
                    const classScores = displayStudents.map(s => s.scores.find(sc => sc.name === header)?.score || 0).filter(score => score >= 0);
                    const avg = classScores.length > 0 ? classScores.reduce((a, b) => a + b, 0) / classScores.length : 0;
                    return (
                      <div key={header}>
                        <div className="flex justify-between text-[10px] font-bold mb-1">
                          <span className="text-slate-500 truncate mr-2">{header}</span>
                          <span className={`${avg >= 8 ? 'text-emerald-600' : avg >= 6.5 ? 'text-indigo-600' : 'text-slate-900'}`}>{avg.toFixed(1)}</span>
                        </div>
                        <div className="w-full h-1 bg-slate-100 rounded-full overflow-hidden">
                          <div 
                            className={`h-full transition-all duration-1000 ${avg >= 8 ? 'bg-emerald-500' : avg >= 6.5 ? 'bg-indigo-500' : 'bg-amber-500'}`} 
                            style={{ width: `${avg * 10}%` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>

            <div className="bg-white rounded-3xl shadow-sm border border-slate-200/60 overflow-hidden">
              <div className="p-6 border-b flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h3 className="font-bold text-slate-900 text-sm">Danh sách học sinh thực tế ({displayStudents.length})</h3>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Tìm tên học sinh..." 
                    className="pl-9 pr-4 py-2 border border-slate-200 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-64 bg-slate-50"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>
              </div>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-50/50 text-slate-400 text-[9px] font-bold uppercase tracking-widest border-b">
