                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {displayStudents.map(student => (
                      <tr key={`${student.className}-${student.name}-${student.id}`} className="hover:bg-slate-50/80 transition-colors">
                        <td className="px-6 py-4">
                          <div className="font-bold text-slate-800 text-sm">{student.name}</div>
                          <div className="text-[10px] text-slate-400 font-bold uppercase">{student.className}</div>
