                        <td className="px-6 py-4">
                          <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold border ${getClassificationColor(student.classification)}`}>
                            {student.classification}
                          </span>
                        </td>
                        <td className="px-6 py-4">
                          {student.goals.slice(0, 1).map(goal => (
                            <div key={goal.subjectName} className="text-xs flex items-center gap-1.5">
                              <span className="font-bold text-slate-600">{goal.subjectName}</span>
                              <span className="text-slate-400">{goal.currentScore}</span>
                              <ChevronRight className="w-3 h-3 text-slate-300" />
                              <span className="text-indigo-600 font-bold">{goal.targetScore.toFixed(1)}</span>
                            </div>
                          ))}
                          {student.goals.length === 0 && <span className="text-[10px] text-slate-400 italic">Duy trì tối đa</span>}
                        </td>
                        <td className="px-6 py-4">
                          <div className="text-[11px] text-slate-500 italic max-w-xs">{student.summary}</div>
                        </td>
                      </tr>
                    ))}
                    {displayStudents.length === 0 && (
                      <tr>
                        <td colSpan={4} className="px-6 py-12 text-center text-slate-400 italic text-sm">Không có dữ liệu phù hợp với bộ lọc.</td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="bg-white border-t py-6 mt-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center text-slate-400 text-[10px] font-bold uppercase tracking-widest">
          <p>© 2024 EduMind System - Giải pháp số hóa quản lý học tập</p>
