import React, { useState, useEffect, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  Upload, 
  FileText, 
  Download, 
  AlertCircle, 
  TrendingUp, 
  Target, 
  Users, 
  ChevronRight,
  Sparkles,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  BarChart3,
  Award,
  Grid,
  Filter,
  Layers,
  LayoutDashboard,
  Trash2,
  School
} from 'lucide-react';
import { StudentData, ClassStats, StudentClassification } from './types';
import { processRawStudentData } from './gradingService';
import { getPedagogicalAdvice } from './geminiService';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie,
  Legend
} from 'recharts';

const App: React.FC = () => {
  const [allStudents, setAllStudents] = useState<StudentData[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [aiAdvice, setAiAdvice] = useState<Record<string, string>>({});
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedClassification, setSelectedClassification] = useState<string>("All");
  const [activeTab, setActiveTab] = useState<string>("SUMMARY"); // "SUMMARY" or ClassName

  // Phân nhóm học sinh theo lớp
  const classGroups = useMemo(() => {
    const groups: Record<string, StudentData[]> = {};
    allStudents.forEach(s => {
      const cls = s.className || "Chưa rõ";
      if (!groups[cls]) groups[cls] = [];
      groups[cls].push(s);
    });
    return groups;
  }, [allStudents]);

  const sortedClassNames = useMemo(() => Object.keys(classGroups).sort(), [classGroups]);

  // Dữ liệu hiển thị dựa trên Tab đang chọn
  const currentViewStudents = useMemo(() => {
    if (activeTab === "SUMMARY") return allStudents;
    return classGroups[activeTab] || [];
  }, [allStudents, classGroups, activeTab]);

  const filteredStudents = useMemo(() => {
    return currentViewStudents.filter(s => {
      const name = s.name || "";
      const matchesSearch = name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = selectedClassification === "All" || s.classification === selectedClassification;
      return matchesSearch && matchesFilter;
    });
  }, [currentViewStudents, searchTerm, selectedClassification]);

  const stats = useMemo((): ClassStats => {
    const list = currentViewStudents;
    return {
      total: list.length,
      totCount: list.filter(s => s.classification === StudentClassification.TOT).length,
      tiemCanTotCount: list.filter(s => s.classification === StudentClassification.TIEM_CAN_TOT).length,
      khaCount: list.filter(s => s.classification === StudentClassification.KHA).length,
      datCount: list.filter(s => s.classification === StudentClassification.DAT).length,
      nguyCoCount: list.filter(s => s.classification === StudentClassification.NGUY_CO).length,
    };
  }, [currentViewStudents]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });

        let newProcessedStudents: StudentData[] = [];
        let newSubjectHeaders: Set<string> = new Set();

        wb.SheetNames.forEach(wsname => {
          const ws = wb.Sheets[wsname];
          const data = XLSX.utils.sheet_to_json<any>(ws, { blankrows: false });

          if (data.length === 0) return;

          const allHeaders = Object.keys(data[0]);
          const nameKey = allHeaders.find(h => {
            const l = h.trim().toLowerCase();
            return ['họ tên', 'họ và tên', 'tên', 'name'].includes(l) || (l.includes('họ') && l.includes('tên'));
          }) || 'Họ tên';

          const classKey = allHeaders.find(h => {
            const l = h.trim().toLowerCase();
            return ['lớp', 'class'].includes(l) || l.includes('lớp');
          }) || 'Lớp';

          const sttKey = allHeaders.find(h => ['stt', 'id', 'no'].includes(h.trim().toLowerCase())) || 'STT';

          const subjectHeaders = allHeaders.filter(h => ![sttKey, nameKey, classKey].includes(h));
          subjectHeaders.forEach(h => newSubjectHeaders.add(h));

          const processed = data.map(item => {
            if (!item[classKey]) item[classKey] = wsname;
            return processRawStudentData(item, subjectHeaders, { nameKey, classKey, sttKey });
          }).filter((s): s is StudentData => s !== null);

          newProcessedStudents = [...newProcessedStudents, ...processed];
        });

        if (newProcessedStudents.length === 0) throw new Error("Không tìm thấy dữ liệu hợp lệ.");

        setHeaders(prev => Array.from(new Set([...prev, ...Array.from(newSubjectHeaders)])));
        setAllStudents(prev => [...prev, ...newProcessedStudents]);
        // Tự động chuyển đến lớp vừa upload nếu chỉ có 1 lớp mới
        const uniqueNewClasses = Array.from(new Set(newProcessedStudents.map(s => s.className)));
        if (uniqueNewClasses.length === 1) setActiveTab(uniqueNewClasses[0]);
      } catch (err: any) {
        setError(err.message || "Lỗi khi xử lý file Excel.");
      } finally {
        setLoading(false);
        e.target.value = ''; // Reset input
      }
    };
    reader.readAsBinaryString(file);
  };

  const loadAiAdvice = async () => {
    if (currentViewStudents.length === 0) return;
    const key = activeTab;
    setAiAdvice(prev => ({ ...prev, [key]: "Đang phân tích..." }));
    const advice = await getPedagogicalAdvice(stats, currentViewStudents);
    setAiAdvice(prev => ({ ...prev, [key]: advice }));
  };

  const clearAllData = () => {
    if (window.confirm("Bạn có chắc chắn muốn xóa toàn bộ dữ liệu hiện có?")) {
      setAllStudents([]);
      setHeaders([]);
      setAiAdvice({});
      setActiveTab("SUMMARY");
    }
  };

  const chartData = [
    { name: 'Tốt', value: stats.totCount, fill: '#10b981' },
    { name: 'Tiệm cận Tốt', value: stats.tiemCanTotCount, fill: '#3b82f6' },
    { name: 'Khá', value: stats.khaCount, fill: '#6366f1' },
    { name: 'Đạt', value: stats.datCount, fill: '#eab308' },
    { name: 'Nguy cơ', value: stats.nguyCoCount, fill: '#f43f5e' },
  ];

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-50">
        <div className="max-w-[1600px] mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-200">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-900 tracking-tight">EduMind <span className="text-indigo-600">Enterprise</span></h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Hệ thống hỗ trợ sư phạm đa lớp</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {allStudents.length > 0 && (
              <button 
                onClick={clearAllData}
                className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-colors border border-transparent hover:border-rose-100"
                title="Xóa tất cả dữ liệu"
              >
                <Trash2 className="w-5 h-5" />
              </button>
            )}
            <label className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 text-sm font-bold">
              <Upload className="w-4 h-4" /> 
              <span className="hidden sm:inline">Thêm dữ liệu lớp</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </header>

      <div className="flex-1 flex max-w-[1600px] mx-auto w-full">
        {/* Sidebar Navigation */}
        <aside className="w-64 border-r bg-white hidden lg:flex flex-col p-4 sticky top-16 h-[calc(100vh-64px)] overflow-y-auto">
          <div className="mb-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 px-2">Bảng điều khiển</h3>
            <button
              onClick={() => setActiveTab("SUMMARY")}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-bold text-sm ${
                activeTab === "SUMMARY" 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' 
                : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <LayoutDashboard className="w-4 h-4" /> Tổng hợp trường
            </button>
          </div>

          <div>
            <div className="flex items-center justify-between mb-4 px-2">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Danh sách lớp ({sortedClassNames.length})</h3>
            </div>
            <div className="space-y-1">
              {sortedClassNames.map(cls => (
                <button
                  key={cls}
                  onClick={() => setActiveTab(cls)}
                  className={`w-full flex items-center justify-between px-4 py-2.5 rounded-lg transition-all text-sm font-bold ${
                    activeTab === cls 
                    ? 'bg-indigo-50 text-indigo-700 border-l-4 border-indigo-600' 
                    : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <span className="truncate">{cls}</span>
                  <span className={`text-[10px] px-1.5 py-0.5 rounded-md ${activeTab === cls ? 'bg-indigo-200/50' : 'bg-slate-100'}`}>
                    {classGroups[cls].length}
                  </span>
                </button>
              ))}
              {sortedClassNames.length === 0 && (
                <div className="px-4 py-8 text-center border-2 border-dashed border-slate-100 rounded-xl">
                  <Layers className="w-8 h-8 text-slate-200 mx-auto mb-2" />
                  <p className="text-[10px] text-slate-400 uppercase font-bold">Chưa có lớp</p>
                </div>
              )}
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-6 overflow-hidden">
          {loading && (
            <div className="mb-6 p-4 bg-indigo-50 border border-indigo-100 rounded-2xl flex items-center gap-3 animate-pulse">
              <div className="w-4 h-4 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" />
              <p className="text-sm font-bold text-indigo-700">Đang đồng bộ hóa dữ liệu thông minh...</p>
            </div>
          )}

          {error && (
            <div className="mb-6 p-4 bg-rose-50 border border-rose-100 text-rose-700 rounded-2xl flex items-center gap-3">
              <AlertCircle className="w-5 h-5" />
              <p className="text-sm font-bold">{error}</p>
            </div>
          )}

          {allStudents.length === 0 && !loading ? (
            <div className="h-full flex flex-col items-center justify-center text-center p-12 bg-white rounded-[40px] border-2 border-dashed border-slate-200">
              <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                <School className="w-12 h-12 text-slate-200" />
              </div>
              <h2 className="text-2xl font-black text-slate-900 mb-2">Chào mừng đến với EduMind Enterprise</h2>
              <p className="text-slate-400 text-sm max-w-md mb-8">
                Hệ thống sẵn sàng quản lý 12+ lớp học. Hãy tải lên file Excel chứa điểm của các lớp (10A1-12C4) để bắt đầu phân tích.
              </p>
              <label className="cursor-pointer px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black hover:bg-indigo-700 transition shadow-xl shadow-indigo-100">
                Tải lên file dữ liệu đầu tiên
                <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
              </label>
            </div>
          ) : (
            <div className="space-y-8 animate-in fade-in duration-500">
              {/* Dashboard Header */}
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                  <div className="flex items-center gap-2 text-indigo-600 mb-1">
                    {activeTab === "SUMMARY" ? <School className="w-4 h-4" /> : <Layers className="w-4 h-4" />}
                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">
                      {activeTab === "SUMMARY" ? "Mô-đun Hệ thống" : `Mô-đun Lớp ${activeTab}`}
                    </span>
                  </div>
                  <h2 className="text-3xl font-black text-slate-900">
                    {activeTab === "SUMMARY" ? "Tổng hợp toàn trường" : `Phân tích chi tiết ${activeTab}`}
                  </h2>
                </div>

                <div className="flex gap-2">
                   <StatCardMini label="Tổng HS" value={stats.total} />
                   <StatCardMini label="Tốt" value={stats.totCount} color="text-emerald-600" />
                   <StatCardMini label="Nguy cơ" value={stats.nguyCoCount} color="text-rose-600" />
                </div>
              </div>

              {/* Stats Overview Grid */}
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Chart Section */}
                <div className="lg:col-span-2 bg-white p-8 rounded-[32px] shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-8">
                    <h3 className="font-black text-slate-900 flex items-center gap-2">
                      <BarChart3 className="w-5 h-5 text-indigo-600" /> Phân bổ học lực học kỳ
                    </h3>
                  </div>
                  <div className="h-72">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData.filter(d => d.value > 0)}>
                        <XAxis dataKey="name" fontSize={10} tickLine={false} axisLine={false} />
                        <YAxis fontSize={10} tickLine={false} axisLine={false} />
                        <Tooltip 
                          cursor={{fill: '#f8fafc'}} 
                          contentStyle={{borderRadius: '24px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)'}} 
                        />
                        <Bar dataKey="value" radius={[12, 12, 0, 0]} barSize={45}>
                          {chartData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={entry.fill} />
                          ))}
                        </Bar>
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                {/* AI & Quick Insights */}
                <div className="space-y-6">
                  <div className="bg-indigo-900 text-white p-8 rounded-[32px] shadow-xl relative overflow-hidden group">
                    <div className="relative z-10">
                      <div className="flex items-center gap-2 mb-4">
                        <Sparkles className="w-5 h-5 text-amber-300" />
                        <h3 className="font-bold text-lg">Chiến lược Sư phạm AI</h3>
                      </div>
                      {aiAdvice[activeTab] ? (
                        <div className="text-sm leading-relaxed text-indigo-100/90 whitespace-pre-line bg-white/5 p-5 rounded-2xl border border-white/10 italic">
                          {aiAdvice[activeTab]}
                        </div>
                      ) : (
                        <div className="text-center py-4">
                          <p className="text-xs text-indigo-300 mb-6">Yêu cầu AI phân tích dữ liệu {activeTab === "SUMMARY" ? "toàn trường" : `lớp ${activeTab}`}.</p>
                          <button 
                            onClick={loadAiAdvice}
                            className="w-full py-3 bg-white text-indigo-900 rounded-2xl text-xs font-black hover:bg-indigo-50 transition shadow-lg"
                          >
                            Bắt đầu phân tích AI
                          </button>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="bg-white p-6 rounded-[32px] border border-slate-100">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Môn học trọng điểm</h4>
                    <div className="space-y-3">
                      {headers.slice(0, 5).map(h => {
                        const scores = currentViewStudents.map(s => s.scores.find(sc => sc.name === h)?.score || 0);
                        const avg = scores.length > 0 ? scores.reduce((a,b)=>a+b,0)/scores.length : 0;
                        return (
                          <div key={h} className="flex items-center justify-between">
                            <span className="text-xs font-bold text-slate-600">{h}</span>
                            <div className="flex items-center gap-2">
                              <div className="w-24 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                <div className="h-full bg-indigo-500" style={{width: `${avg*10}%`}} />
                              </div>
                              <span className="text-[10px] font-black text-slate-900 w-6 text-right">{avg.toFixed(1)}</span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              </div>

              {/* List Section */}
              <div className="bg-white rounded-[40px] shadow-sm border border-slate-100 overflow-hidden">
                <div className="p-8 border-b flex flex-col md:flex-row md:items-center justify-between gap-6">
                  <div>
                    <h3 className="text-xl font-black text-slate-900 mb-1">Cơ sở dữ liệu học tập</h3>
                    <p className="text-xs text-slate-400 font-medium">Quản lý và theo dõi lộ trình tiến bộ của từng cá nhân.</p>
                  </div>

                  <div className="flex flex-wrap gap-3">
                    <div className="relative">
                      <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
                      <input 
                        type="text" 
                        placeholder="Tìm học sinh..." 
                        className="pl-11 pr-6 py-3 bg-slate-50 border-none rounded-2xl text-sm focus:ring-2 focus:ring-indigo-500 w-full sm:w-64"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                      />
                    </div>
                    <select 
                      className="px-6 py-3 bg-slate-50 border-none rounded-2xl text-sm font-bold text-slate-600 focus:ring-2 focus:ring-indigo-500 appearance-none"
                      value={selectedClassification}
                      onChange={(e) => setSelectedClassification(e.target.value)}
                    >
                      <option value="All">Mọi kết quả</option>
                      {Object.values(StudentClassification).map(v => <option key={v} value={v}>{v}</option>)}
                    </select>
                  </div>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="bg-slate-50/50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                        <th className="px-8 py-5">Định danh</th>
                        <th className="px-8 py-5">Xếp loại</th>
                        <th className="px-8 py-5">Mục tiêu ưu tiên</th>
                        <th className="px-8 py-5">Ghi chú chiến lược</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredStudents.length > 0 ? filteredStudents.map(s => (
                        <tr key={`${s.className}-${s.id}-${s.name}`} className="group hover:bg-indigo-50/20 transition-colors">
                          <td className="px-8 py-6">
                            <div className="font-black text-slate-900 text-sm mb-0.5">{s.name}</div>
                            <div className="text-[10px] font-black text-indigo-500 bg-indigo-50 w-fit px-1.5 py-0.5 rounded uppercase">{s.className}</div>
                          </td>
                          <td className="px-8 py-6">
                            <span className={`px-3 py-1 rounded-xl text-[10px] font-black border shadow-sm ${getClassificationStyles(s.classification)}`}>
                              {s.classification}
                            </span>
                          </td>
                          <td className="px-8 py-6">
                            {s.goals.slice(0, 1).map(g => (
                              <div key={g.subjectName} className="flex items-center gap-2 text-xs">
                                <span className="font-black text-slate-700">{g.subjectName}</span>
                                <span className="text-slate-300">|</span>
                                <span className="text-indigo-600 font-black">{g.currentScore} → {g.targetScore.toFixed(1)}</span>
                              </div>
                            ))}
                            {s.goals.length === 0 && <span className="text-[10px] text-slate-400 font-bold uppercase italic">Duy trì tối đa</span>}
                          </td>
                          <td className="px-8 py-6">
                            <p className="text-[11px] text-slate-500 font-medium leading-relaxed max-w-xs line-clamp-2">{s.summary}</p>
                          </td>
                        </tr>
                      )) : (
                        <tr>
                          <td colSpan={4} className="px-8 py-20 text-center">
                            <Layers className="w-12 h-12 text-slate-100 mx-auto mb-4" />
                            <p className="text-slate-400 text-sm font-medium">Không có kết quả nào khớp với tìm kiếm của bạn.</p>
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

const StatCardMini: React.FC<{ label: string; value: number; color?: string }> = ({ label, value, color = "text-slate-900" }) => (
  <div className="bg-white px-5 py-3 rounded-2xl border border-slate-100 flex flex-col items-center justify-center min-w-[100px] shadow-sm">
    <span className="text-[9px] font-black text-slate-400 uppercase tracking-wider mb-0.5">{label}</span>
    <span className={`text-lg font-black ${color}`}>{value}</span>
  </div>
);

const getClassificationStyles = (cls: StudentClassification) => {
  switch (cls) {
    case StudentClassification.TOT: return 'bg-emerald-500 text-white border-emerald-400';
    case StudentClassification.TIEM_CAN_TOT: return 'bg-blue-500 text-white border-blue-400';
    case StudentClassification.KHA: return 'bg-indigo-500 text-white border-indigo-400';
    case StudentClassification.DAT: return 'bg-amber-500 text-white border-amber-400';
    case StudentClassification.NGUY_CO: return 'bg-rose-500 text-white border-rose-400';
    default: return 'bg-slate-100 text-slate-600 border-slate-200';
  }
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  Upload, 
  FileText, 
  Download, 
  AlertCircle, 
  TrendingUp, 
  Target, 
  Users, 
  ChevronRight,
  Sparkles,
  Search,
  CheckCircle2,
  XCircle,
  HelpCircle,
  BarChart3,
  Award,
  Grid,
  Filter,
  Layers,
  LayoutDashboard,
  Trash2,
  School,
  FileSpreadsheet
} from 'lucide-react';
import { StudentData, ClassStats, StudentClassification } from './types';
import { processRawStudentData } from './gradingService';
import { getPedagogicalAdvice } from './geminiService';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip, 
  ResponsiveContainer, 
  Cell,
  PieChart,
  Pie,
  Legend
} from 'recharts';

const App: React.FC = () => {
  const [allStudents, setAllStudents] = useState<StudentData[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [aiAdvice, setAiAdvice] = useState<Record<string, string>>({});
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedClassification, setSelectedClassification] = useState<string>("All");
  const [activeTab, setActiveTab] = useState<string>("SUMMARY"); // "SUMMARY" or ClassName

  // Phân nhóm học sinh theo lớp
  const classGroups = useMemo(() => {
    const groups: Record<string, StudentData[]> = {};
    allStudents.forEach(s => {
      const cls = s.className || "Chưa rõ";
      if (!groups[cls]) groups[cls] = [];
      groups[cls].push(s);
    });
    return groups;
  }, [allStudents]);

  const sortedClassNames = useMemo(() => Object.keys(classGroups).sort(), [classGroups]);

  // Thống kê chi tiết từng lớp cho bảng tổng hợp
  const schoolDetailedStats = useMemo(() => {
    return sortedClassNames.map(cls => {
      const students = classGroups[cls];
      return {
        className: cls,
        total: students.length,
        tot: students.filter(s => s.classification === StudentClassification.TOT).length,
        tiemCanTot: students.filter(s => s.classification === StudentClassification.TIEM_CAN_TOT).length,
        kha: students.filter(s => s.classification === StudentClassification.KHA).length,
        dat: students.filter(s => s.classification === StudentClassification.DAT).length,
        nguyCo: students.filter(s => s.classification === StudentClassification.NGUY_CO).length,
      };
    });
  }, [classGroups, sortedClassNames]);

  // Dữ liệu hiển thị dựa trên Tab đang chọn
  const currentViewStudents = useMemo(() => {
    if (activeTab === "SUMMARY") return allStudents;
    return classGroups[activeTab] || [];
  }, [allStudents, classGroups, activeTab]);

  const filteredStudents = useMemo(() => {
    return currentViewStudents.filter(s => {
      const name = s.name || "";
      const matchesSearch = name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = selectedClassification === "All" || s.classification === selectedClassification;
      return matchesSearch && matchesFilter;
    });
  }, [currentViewStudents, searchTerm, selectedClassification]);

  const stats = useMemo((): ClassStats => {
    const list = currentViewStudents;
    return {
      total: list.length,
      totCount: list.filter(s => s.classification === StudentClassification.TOT).length,
      tiemCanTotCount: list.filter(s => s.classification === StudentClassification.TIEM_CAN_TOT).length,
      khaCount: list.filter(s => s.classification === StudentClassification.KHA).length,
      datCount: list.filter(s => s.classification === StudentClassification.DAT).length,
      nguyCoCount: list.filter(s => s.classification === StudentClassification.NGUY_CO).length,
    };
  }, [currentViewStudents]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setError(null);
    const reader = new FileReader();

    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });

        let newProcessedStudents: StudentData[] = [];
        let newSubjectHeaders: Set<string> = new Set();

        wb.SheetNames.forEach(wsname => {
          const ws = wb.Sheets[wsname];
          const data = XLSX.utils.sheet_to_json<any>(ws, { blankrows: false });

          if (data.length === 0) return;

          const allHeaders = Object.keys(data[0]);
          const nameKey = allHeaders.find(h => {
            const l = h.trim().toLowerCase();
            return ['họ tên', 'họ và tên', 'tên', 'name'].includes(l) || (l.includes('họ') && l.includes('tên'));
          }) || 'Họ tên';

          const classKey = allHeaders.find(h => {
            const l = h.trim().toLowerCase();
            return ['lớp', 'class'].includes(l) || l.includes('lớp');
          }) || 'Lớp';

          const sttKey = allHeaders.find(h => ['stt', 'id', 'no'].includes(h.trim().toLowerCase())) || 'STT';

          const subjectHeaders = allHeaders.filter(h => ![sttKey, nameKey, classKey].includes(h));
          subjectHeaders.forEach(h => newSubjectHeaders.add(h));

          const processed = data.map(item => {
            if (!item[classKey]) item[classKey] = wsname;
            return processRawStudentData(item, subjectHeaders, { nameKey, classKey, sttKey });
          }).filter((s): s is StudentData => s !== null);

          newProcessedStudents = [...newProcessedStudents, ...processed];
        });

        if (newProcessedStudents.length === 0) throw new Error("Không tìm thấy dữ liệu hợp lệ.");

        setHeaders(prev => Array.from(new Set([...prev, ...Array.from(newSubjectHeaders)])));
        setAllStudents(prev => [...prev, ...newProcessedStudents]);
        const uniqueNewClasses = Array.from(new Set(newProcessedStudents.map(s => s.className)));
        if (uniqueNewClasses.length === 1) setActiveTab(uniqueNewClasses[0]);
      } catch (err: any) {
        setError(err.message || "Lỗi khi xử lý file Excel.");
      } finally {
        setLoading(false);
        e.target.value = ''; 
      }
    };
    reader.readAsBinaryString(file);
  };

  const loadAiAdvice = async () => {
    if (currentViewStudents.length === 0) return;
    const key = activeTab;
    setAiAdvice(prev => ({ ...prev, [key]: "Đang phân tích..." }));
    const advice = await getPedagogicalAdvice(stats, currentViewStudents);
    setAiAdvice(prev => ({ ...prev, [key]: advice }));
  };

  const clearAllData = () => {
    if (window.confirm("Bạn có chắc chắn muốn xóa toàn bộ dữ liệu hiện có?")) {
      setAllStudents([]);
      setHeaders([]);
      setAiAdvice({});
      setActiveTab("SUMMARY");
    }
  };

  const exportToExcel = () => {
    const wb = XLSX.utils.book_new();

    if (activeTab === "SUMMARY") {
      // 1. Sheet Thống kê chi tiết các lớp
      const statsData = schoolDetailedStats.map(s => ({
        'Tên lớp': s.className,
        'Tổng số HS': s.total,
        'Học sinh Tốt': s.tot,
        'Tiệm cận Tốt': s.tiemCanTot,
        'Học sinh Khá': s.kha,
        'Học sinh Đạt': s.dat,
        'Nguy cơ': s.nguyCo
      }));
      const wsStats = XLSX.utils.json_to_sheet(statsData);
      XLSX.utils.book_append_sheet(wb, wsStats, "Thống kê các lớp");

      // 2. Sheet Danh sách toàn trường
      const studentData = allStudents.map(s => ({
        'STT': s.id,
        'Họ tên': s.name,
        'Lớp': s.className,
        'Xếp loại': s.classification,
        'Ghi chú': s.summary,
        'Môn cần bồi dưỡng': s.prioritySubjects.join(', '),
        'Mục tiêu tiến bộ': s.goals.map(g => `${g.subjectName}(${g.currentScore}->${g.targetScore.toFixed(1)})`).join('; ')
      }));
      const wsStudents = XLSX.utils.json_to_sheet(studentData);
      XLSX.utils.book_append_sheet(wb, wsStudents, "Toàn bộ học sinh");

      XLSX.writeFile(wb, "Bao_cao_tong_hop_Truong.xlsx");
    } else {
      // Xuất cho lớp cụ thể
      const studentsInClass = classGroups[activeTab] || [];
      const classData = studentsInClass.map(s => {
        const base: any = {
          'STT': s.id,
          'Họ tên': s.name,
          'Xếp loại': s.classification,
          'Ghi chú sư phạm': s.summary,
          'Môn trọng tâm': s.prioritySubjects.join(', ')
        };
        // Thêm điểm các môn
        s.scores.forEach(sc => {
          base[sc.name] = sc.score;
        });
        return base;
      });
      const wsClass = XLSX.utils.json_to_sheet(classData);
      XLSX.utils.book_append_sheet(wb, wsClass, `Kết quả lớp ${activeTab}`);

      // Thêm sheet mục tiêu
      const goalsData = studentsInClass.flatMap(s => s.goals.map(g => ({
        'Học sinh': s.name,
        'Môn học': g.subjectName,
        'Điểm hiện tại': g.currentScore,
        'Điểm mục tiêu': g.targetScore,
        'Cần tăng': g.increment.toFixed(1),
        'Lộ trình': g.description
      })));
      const wsGoals = XLSX.utils.json_to_sheet(goalsData);
      XLSX.utils.book_append_sheet(wb, wsGoals, "Mục tiêu tiến bộ");

      XLSX.writeFile(wb, `Ket_qua_lop_${activeTab.replace(/\s/g, '_')}.xlsx`);
    }
  };

  const chartData = [
    { name: 'Tốt', value: stats.totCount, fill: '#10b981' },
    { name: 'Tiệm cận Tốt', value: stats.tiemCanTotCount, fill: '#3b82f6' },
    { name: 'Khá', value: stats.khaCount, fill: '#6366f1' },
    { name: 'Đạt', value: stats.datCount, fill: '#eab308' },
    { name: 'Nguy cơ', value: stats.nguyCoCount, fill: '#f43f5e' },
  ];

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <header className="bg-white border-b sticky top-0 z-50">
        <div className="max-w-[1600px] mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-200">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-900 tracking-tight">EduMind <span className="text-indigo-600">Enterprise</span></h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Quản lý Chất lượng Giáo dục TT22</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            {allStudents.length > 0 && (
              <>
                <button 
                  onClick={exportToExcel}
                  className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl hover:bg-slate-50 transition shadow-sm text-sm font-bold"
                >
                  <Download className="w-4 h-4 text-indigo-600" />
                  <span className="hidden sm:inline">Xuất Excel {activeTab === "SUMMARY" ? "Toàn trường" : "Lớp"}</span>
                </button>
                <button 
                  onClick={clearAllData}
                  className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg transition-colors border border-transparent hover:border-rose-100"
                >
                  <Trash2 className="w-5 h-5" />
                </button>
              </>
            )}
            <label className="cursor-pointer flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 text-sm font-bold">
              <Upload className="w-4 h-4" /> 
              <span className="hidden sm:inline">Thêm dữ liệu</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </header>

      <div className="flex-1 flex max-w-[1600px] mx-auto w-full">
        <aside className="w-64 border-r bg-white hidden lg:flex flex-col p-4 sticky top-16 h-[calc(100vh-64px)] overflow-y-auto">
          <div className="mb-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 px-2">Bảng điều khiển</h3>
            <button
              onClick={() => setActiveTab("SUMMARY")}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-bold text-sm ${
                activeTab === "SUMMARY" 
                ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' 
                : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <LayoutDashboard className="w-4 h-4" /> Tổng hợp trường
            </button>
          </div>

          <div>
            <div className="flex items-center justify-between mb-4 px-2">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Cơ cấu lớp học ({sortedClassNames.length})</h3>
            </div>
            <div className="space-y-1">
              {sortedClassNames.map(cls => (
                <button
                  key={cls}
                  onClick={() => setActiveTab(cls)}
                  className={`w-full flex items-center justify-between px-4 py-2.5 rounded-lg transition-all text-sm font-bold ${
                    activeTab === cls 
                    ? 'bg-indigo-50 text-indigo-700 border-l-4 border-indigo-600' 
                    : 'text-slate-500 hover:bg-slate-50'
                  }`}
                >
                  <span className="truncate">{cls}</span>
                  <span className={`text-[10px] px-1.5 py-0.5 rounded-md ${activeTab === cls ? 'bg-indigo-200/50' : 'bg-slate-100'}`}>
                    {classGroups[cls].length}
                  </span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-1 p-6 overflow-hidden">
          {loading && (
            <div className="mb-6 p-4 bg-indigo-50 border border-indigo-100 rounded-2xl flex items-center gap-3 animate-pulse">
              <div className="w-4 h-4 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" />
              <p className="text-sm font-bold text-indigo-700">Đang đồng bộ hóa dữ liệu...</p>
            </div>
          )}

          {allStudents.length === 0 && !loading ? (
            <div className="h-full flex flex-col items-center justify-center text-center p-12 bg-white rounded-[40px] border-2 border-dashed border-slate-200">
              <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                <School className="w-12 h-12 text-slate-200" />
              </div>
              <h2 className="text-2xl font-black text-slate-900 mb-2">Trung tâm Phân tích Dữ liệu EduMind</h2>
              <p className="text-slate-400 text-sm max-w-md mb-8">
                Hệ thống hỗ trợ xuất báo cáo chi tiết cho từng lớp và báo cáo tổng hợp toàn trường theo chuẩn Thông tư 22.
              </p>
              <label className="cursor-pointer px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black hover:bg-indigo-700 transition shadow-xl shadow-indigo-100">
                Bắt đầu bằng việc tải file Excel
                <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
              </label>
            </div>
          ) : (
            <div className="space-y-8 animate-in fade-in duration-500">
              <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                  <div className="flex items-center gap-2 text-indigo-600 mb-1">
                    {activeTab === "SUMMARY" ? <School className="w-4 h-4" /> : <Layers className="w-4 h-4" />}
                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">
                      {activeTab === "SUMMARY" ? "Mô-đun Tổng quát" : `Chi tiết Lớp ${activeTab}`}
                    </span>
                  </div>
                  <h2 className="text-3xl font-black text-slate-900 tracking-tight">
                    {activeTab === "SUMMARY" ? "Tổng hợp chất lượng trường" : `Phân tích dữ liệu ${activeTab}`}
                  </h2>
                </div>

                <div className="flex gap-2">
                   <StatCardMini label="Tổng HS" value={stats.total} />
                   <StatCardMini label="Tốt" value={stats.totCount} color="text-emerald-600" />
                   <StatCardMini label="Nguy cơ" value={stats.nguyCoCount} color="text-rose-600" />
                </div>
              </div>

              {/* Stats Overview Grid */}
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white p-8 rounded-[32px] shadow-sm border border-slate-100">
                  <div className="flex items-center justify-between mb-8">
                    <h3 className="font-black text-slate-900 flex items-center gap-2">
                      <BarChart3 className="w-5 h-5 text-indigo-600" /> Phân bổ học lực
                    </h3>
                  </div>
                  <div className="h-72">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={chartData.filter(d => d.value > 0)}>
                        <XAxis dataKey="name" fontSize={10} tickLine={false} axisLine={false} />
                        <YAxis fontSize={10} tickLine={false} axisLine={false} />
                        <Tooltip 
                          cursor={{fill: '#f8fafc'}} 
                          contentStyle={{borderRadius: '24px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)'}} 
