// gradingService.ts
export interface SubjectScore {
  name: string;
  score: number;
}

export interface Goal {
  subjectName: string;
  currentScore: number;
  targetScore: number;
  increment: number;
  description: string;
}

export function calculateGoals(subjectScores: SubjectScore[]): Goal[] {
  const goals: Goal[] = [];

  subjectScores.forEach((s) => {
    // 6.0 <= score < 6.5 -> Mục tiêu 6.5
    if (s.score >= 6.0 && s.score < 6.5) {
      goals.push({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 6.5,
        increment: 6.5 - s.score,
        description: "Phấn đấu nâng lên mức Khá (6.5)",
      });
    }
    // 3.5 <= score < 5.0 -> Mục tiêu 5.0
    else if (s.score >= 3.5 && s.score < 5.0) {
      goals.push({
        subjectName: s.name,
        currentScore: s.score,
        targetScore: 5.0,
        increment: 5.0 - s.score,
        description: "Phấn đấu đạt ngưỡng Đạt (5.0)",
      });
    }
  });

  return goals;
}
