}

export enum StudentClassification {
  TOT = 'Học sinh TỐT',
  TIEM_CAN_TOT = 'Tiệm cận TỐT',
  KHA = 'Học sinh KHÁ',
  TIEM_CAN_KHA = 'Tiệm cận KHÁ',
  DAT = 'Học sinh ĐẠT',
  TIEM_CAN_DAT = 'Tiệm cận ĐẠT',
  CHUA_DAT = 'CHƯA ĐẠT',
}

export interface SubjectScore {
