                            <span className={`px-3 py-1 rounded-xl text-[12px] font-black border shadow-sm ${getClassificationStyles(s.classification)}`}>{s.classification}</span>
                          </td>
                          <td className="px-8 py-6">
                            {s.goals.length > 0 ? (
                              <div className="flex items-center gap-1 font-black text-slate-700">
                                {s.goals[0].subjectName} <ChevronRight className="w-3 h-3 text-indigo-400" /> <span className="text-emerald-600">{s.goals[0].targetScore.toFixed(1)}</span>
                              </div>
                            ) : <span className="text-slate-300 italic text-sm">Duy trì</span>}
                          </td>
                          <td className="px-8 py-6">
                            <div className="text-sm font-medium text-slate-600 leading-tight">
                              {s.goals.length > 0 ? s.goals.slice(0, 2).map((g, i) => (
                                <div key={i} className="mb-1">{g.subjectName}: {g.currentScore} → {g.targetScore.toFixed(1)}</div>
                              )) : (s.classification === StudentClassification.TOT ? "Tiếp tục bồi dưỡng nâng cao." : "Tập trung các môn dưới 5.0")}
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
