        useCORS: true,
        backgroundColor: null
      });
      const link = document.createElement('a');
      link.download = `The_Muc_Tieu_${selectedStudentForCard.name.replace(/\s/g, '_')}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
