                <div className="p-3 bg-amber-500 rounded-2xl shadow-lg shadow-amber-100">
                  <SlidersHorizontal className="w-6 h-6 text-white" />
                </div>
                <div>
                  <h3 className="text-2xl font-black text-slate-900">Giả lập Điểm số (What-if)</h3>
                  <p className="text-sm font-bold text-slate-400">Điều chỉnh điểm để xem dự báo xếp loại mới cho <span className="text-indigo-600">{simulatingStudent.name}</span></p>
                </div>
              </div>
              <button onClick={() => setSimulatingStudent(null)} className="p-3 bg-slate-100 hover:bg-slate-200 rounded-full transition-colors">
