                          className="w-16 px-2 py-1 bg-white border border-slate-200 rounded-lg text-sm font-black text-center focus:ring-2 focus:ring-indigo-500 focus:outline-none"
                        />
                        <span className="text-[10px] font-black text-slate-400 uppercase">Điểm</span>
                      </div>
                    </div>
                    <input 
                      type="range" 
                      min="0" 
                      max="10" 
                      step="0.1" 
                      value={s.score}
                      onChange={(e) => updateSimulatedScore(s.name, parseFloat(e.target.value))}
                      className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
                    />
                    <div className="flex justify-between mt-2">
                       <span className="text-[9px] font-bold text-slate-300 italic">Hiện tại: {simulatingStudent.scores.find(os => os.name === s.name)?.score}</span>
                       <span className={`text-[10px] font-black uppercase tracking-tighter ${s.score >= 8 ? 'text-emerald-500' : s.score >= 6.5 ? 'text-indigo-500' : 'text-slate-400'}`}>
                         {getSubjectLevel(s.score)}
                       </span>
                    </div>
                  </div>
                ))}
              </div>

              {/* Result Area */}
              <div className="w-full lg:w-80 shrink-0 space-y-6">
                <div className="bg-slate-900 rounded-[32px] p-8 text-white shadow-2xl relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/20 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                  <h4 className="text-[10px] font-black text-white/50 uppercase tracking-[0.2em] mb-6">Dự báo Xếp loại</h4>

                  <div className="space-y-6 relative z-10">
                    <div className="flex flex-col items-center text-center">
                      <div className="text-[10px] font-bold text-slate-400 line-through mb-1">{simulatingStudent.classification}</div>
                      <ArrowRight className="w-4 h-4 text-white/20 mb-1" />
                      <div className={`px-5 py-2 rounded-2xl text-sm font-black uppercase border shadow-lg ${getClassificationStyles(simulationResult?.classification as StudentClassification)}`}>
                        {simulationResult?.classification}
                      </div>
                    </div>

                    <div className="pt-6 border-t border-white/10">
                      <p className="text-xs text-white/70 italic leading-relaxed text-center">
                        {simulationResult?.classification === simulatingStudent.classification 
                          ? "Cần nỗ lực thêm ở các môn trọng điểm để bứt phá lên mức cao hơn."
                          : "Chúc mừng! Với mức điểm này, học sinh sẽ thăng hạng vượt trội."}
                      </p>
                    </div>
                  </div>
                </div>

                <div className="bg-white rounded-[32px] border border-slate-100 p-8 shadow-sm">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <Target className="w-4 h-4 text-rose-500" /> Phân tích Mục tiêu
                  </h4>
                  <div className="space-y-4">
                    {simulationResult?.goals.map((g, i) => (
                      <div key={i} className="flex items-center justify-between p-3 bg-slate-50 rounded-2xl border border-slate-100">
                        <span className="text-xs font-bold text-slate-700">{g.subjectName}</span>
                        <div className="flex items-center gap-2">
                          <span className="text-xs font-black text-indigo-600">+{g.increment.toFixed(1)}</span>
                        </div>
                      </div>
                    ))}
                    {simulationResult?.goals.length === 0 && (
                      <div className="text-center py-4">
                        <p className="text-xs text-emerald-600 font-black italic uppercase">Đạt phong độ hoàn hảo</p>
                      </div>
                    )}
                  </div>
                </div>

                <button 
                  onClick={() => setSimulatedScores([...simulatingStudent.scores])}
                  className="w-full py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-sm flex items-center justify-center gap-2 hover:bg-slate-200 transition"
                >
                  <RefreshCcw className="w-4 h-4" /> Khôi phục ban đầu
                </button>
              </div>
            </div>

            <div className="p-8 bg-slate-50 border-t shrink-0 flex justify-end gap-4">
              <button 
                onClick={() => setSimulatingStudent(null)}
                className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition"
              >
                Hoàn tất xem dự báo
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Thẻ Mục Tiêu */}
      {selectedStudentForCard && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="relative w-full max-w-2xl bg-white rounded-[40px] shadow-2xl overflow-hidden animate-in zoom-in duration-300">
            <button onClick={() => setSelectedStudentForCard(null)} className="absolute top-6 right-6 p-2 bg-slate-100 hover:bg-slate-200 rounded-full transition-colors z-20"><X className="w-5 h-5 text-slate-600" /></button>
            <div ref={cardRef} className="p-8 bg-white overflow-hidden relative">
              <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-600/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
              <div className="absolute bottom-0 left-0 w-48 h-48 bg-emerald-600/5 rounded-full -ml-24 -mb-24 blur-3xl"></div>
              <div className="relative border-4 border-double border-slate-200 rounded-[32px] p-8">
                <div className="flex justify-between items-start mb-8">
                  <div className="flex items-center gap-3">
                    <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-200"><Trophy className="w-8 h-8 text-white" /></div>
                    <div>
                      <h4 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Tấm Vé Bứt Phá</h4>
                      <p className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">EduMind Student Milestone 2024</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-black text-slate-400 uppercase tracking-tighter">Class</p>
                    <p className="text-2xl font-black text-slate-900">{selectedStudentForCard.className}</p>
                  </div>
                </div>
                <div className="mb-10">
                  <p className="text-sm font-bold text-slate-400 uppercase mb-1">Học sinh vinh danh</p>
                  <h3 className="text-4xl font-black text-slate-900 tracking-tight">{selectedStudentForCard.name}</h3>
                  <div className="mt-3 flex items-center gap-2">
                    <span className={`px-4 py-1.5 rounded-full text-xs font-black uppercase tracking-wider ${getClassificationStyles(selectedStudentForCard.classification)}`}>{selectedStudentForCard.classification}</span>
                    <div className="h-px flex-1 bg-slate-100"></div>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-8 mb-8">
                  <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100">
                    <h5 className="flex items-center gap-2 text-xs font-black text-slate-400 uppercase mb-4"><Target className="w-4 h-4 text-rose-500" /> Mục tiêu bứt phá</h5>
                    <div className="space-y-3">
                      {selectedStudentForCard.goals.length > 0 ? selectedStudentForCard.goals.map((g, i) => (
                        <div key={i} className="flex items-center justify-between group">
                          <span className="text-sm font-bold text-slate-700">{g.subjectName}</span>
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-slate-400 line-through">{g.currentScore}</span>
                            <ChevronRight className="w-3 h-3 text-indigo-400" />
                            <span className="text-sm font-black text-emerald-600">{g.targetScore.toFixed(1)}</span>
                          </div>
                        </div>
                      )) : (
                        <div className="flex items-center gap-3 text-emerald-600"><Star className="w-4 h-4 fill-emerald-600" /><span className="text-sm font-black uppercase">Duy trì phong độ Tốt</span></div>
                      )}
                    </div>
                  </div>
                  <div className="bg-indigo-600 p-6 rounded-3xl text-white shadow-xl shadow-indigo-100 relative overflow-hidden">
                    <Zap className="absolute -right-4 -bottom-4 w-24 h-24 text-white/10" />
                    <h5 className="text-[10px] font-black text-white/60 uppercase mb-3">Lời nhắn từ EduMind</h5>
                    <p className="text-sm font-medium leading-relaxed italic relative z-10">"Sự kiên trì là chìa khóa của thành công. Hãy tập trung vào mục tiêu để bứt phá!"</p>
                  </div>
                </div>
                <div className="pt-6 border-t border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-2"><Sparkles className="w-4 h-4 text-amber-400" /><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">Success is a journey, not a destination</p></div>
                  <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center border-2 border-slate-100"><Award className="w-6 h-6 text-slate-200" /></div>
                </div>
              </div>
