            <div className="p-8 bg-slate-50 flex gap-4">
              <button onClick={downloadStudentCard} disabled={exporting} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black text-sm flex items-center justify-center gap-2 hover:bg-indigo-700 transition shadow-xl shadow-indigo-100 disabled:opacity-50">
                {exporting ? <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : <ImageIcon className="w-5 h-5" />} Tải Thẻ Ảnh Mục Tiêu
              </button>
              <button onClick={() => setSelectedStudentForCard(null)} className="px-8 py-4 bg-white text-slate-600 rounded-2xl font-black text-sm border border-slate-200 hover:bg-slate-50 transition">Đóng</button>
