          <div className="flex items-center gap-2">
            <button onClick={exportToExcelFormatted} className="flex items-center gap-2 px-4 py-2 bg-white text-slate-700 rounded-xl hover:bg-slate-50 transition border border-slate-200 shadow-sm text-sm font-bold no-print"><FileSpreadsheet className="w-4 h-4 text-emerald-600" /> <span>Xuất Excel Đẹp</span></button>
