                        <div className="h-2 w-full bg-slate-100 rounded-full overflow-hidden"><div className={`h-full transition-all duration-1000 ${getAverageColor(sub.average)}`} style={{ width: `${(sub.average / 10) * 100}%` }}></div></div>
